// 病句 코스 4 — tools/make_bingju.py 가 tools/bingju/c04.json 에서 만든다. 직접 고치지 않는다.
(window.BJ=window.BJ||{})[4]=[[{"o":["通过对长三角地区四十多个城市的跟踪调研，使研究人员发现，轨道交通的完善显著提升了周边商业的活力。","蹴鞠是中国古代的一种球类游戏，盛行于唐宋时期，国际足联已确认足球起源于山东淄博临淄。","近年来，不少传统制造企业借助数字化改造降低了生产成本，在激烈的市场竞争中站稳了脚跟。","丹顶鹤性情温和，体态优雅，在中国传统文化中常被视为长寿与吉祥的象征。"],"a":0,"type":"주어 결여","why":"“通过……，使研究人员发现”에서 通过와 使가 함께 쓰여 ‘研究人员’이 주어가 되지 못하고, 문장에 주어가 없다.","fix":"通过对长三角地区四十多个城市的跟踪调研，研究人员发现，轨道交通的完善显著提升了周边商业的活力。","words":[["跟踪","gēnzōng","추적하다"],["调研","diàoyán","조사 연구"],["站稳脚跟","zhànwěn jiǎogēn","발판을 굳히다"],["丹顶鹤","dāndǐnghè","두루미"],["吉祥","jíxiáng","상서로움"],["蹴鞠","cùjū","축국(옛 공차기)"],["临淄","Línzī","린쯔(지명)"]],"tr":["장강 삼각주 지역 40여 개 도시를 추적 조사한 결과, 연구진은 도시철도가 잘 갖춰지면서 주변 상권의 활력이 크게 높아졌다는 것을 발견했다.","축국은 중국 고대의 공놀이로 당송 시대에 성행했으며, 국제축구연맹은 축구가 산둥 쯔보 린쯔에서 시작되었다고 인정했다.","최근 몇 년 동안 많은 전통 제조 기업이 디지털 전환으로 생산 원가를 낮추고, 치열한 시장 경쟁 속에서 자리를 굳혔다.","두루미는 성질이 온순하고 자태가 우아하여, 중국 전통문화에서 흔히 장수와 행운의 상징으로 여겨진다."],"ow":[[["长三角","Chángsānjiǎo","장강 삼각주"],["跟踪","gēnzōng","추적하다"],["调研","diàoyán","조사 연구"],["轨道交通","guǐdào jiāotōng","도시철도"]],[["蹴鞠","cùjū","축국(옛 공차기)"],["盛行","shèngxíng","성행하다"],["淄博","Zībó","쯔보(지명)"],["临淄","Línzī","린쯔(지명)"]],[["数字化","shùzìhuà","디지털화"],["改造","gǎizào","개조하다"],["站稳了脚跟","zhànwěn le jiǎogēn","발판을 굳혔다"]],[["丹顶鹤","dāndǐnghè","두루미"],["体态","tǐtài","자태"],["优雅","yōuyǎ","우아하다"],["吉祥","jíxiáng","상서로움"]]]},{"o":["篮球运动由美国体育教师奈史密斯于1891年发明，最初是用两个桃子筐当作球篮的。","随着共享单车在各大城市的迅速普及，让“最后一公里”的出行难题得到了有效缓解。","据统计，我国六十岁及以上人口已超过两亿八千万，人口老龄化程度正在持续加深。","珊瑚礁的面积虽然不到海洋总面积的百分之一，却孕育了约四分之一的海洋物种。"],"a":1,"type":"주어 결여","why":"“随着……，让……难题得到了缓解”에서 随着 구 뒤에 让이 와서 주어가 사라졌다.","fix":"随着共享单车在各大城市的迅速普及，“最后一公里”的出行难题得到了有效缓解。","words":[["普及","pǔjí","널리 보급되다"],["缓解","huǎnjiě","완화하다"],["老龄化","lǎolínghuà","고령화"],["珊瑚礁","shānhújiāo","산호초"],["孕育","yùnyù","길러 내다"],["奈史密斯","Nàishǐmìsī","네이스미스"]],"tr":["농구는 1891년 미국 체육 교사 네이스미스가 만들었으며, 처음에는 복숭아 바구니 두 개를 골대로 썼다.","공유 자전거가 대도시마다 빠르게 퍼지면서 ‘마지막 1킬로미터’ 이동 문제가 크게 줄었다.","통계에 따르면 우리나라의 60세 이상 인구는 이미 2억 8천만 명을 넘었고, 고령화는 계속 깊어지고 있다.","산호초는 면적이 바다 전체의 1%도 되지 않지만, 바다 생물 종의 약 4분의 1을 길러 낸다."],"ow":[[["奈史密斯","Nàishǐmìsī","네이스미스"],["桃子筐","táozi kuāng","복숭아 바구니"],["当作","dàngzuò","~로 삼다"]],[["共享单车","gòngxiǎng dānchē","공유 자전거"],["普及","pǔjí","널리 보급되다"],["缓解","huǎnjiě","완화되다"]],[["据统计","jù tǒngjì","통계에 따르면"],["老龄化","lǎolínghuà","고령화"],["加深","jiāshēn","깊어지다"]],[["珊瑚礁","shānhújiāo","산호초"],["孕育","yùnyù","길러 내다"],["物种","wùzhǒng","생물 종"]]]},{"o":["鉴于部分地区房租上涨过快，当地政府出台了一系列措施，以保障新市民和青年人的住房需求。","宋代瓷器以釉色温润、造型简约著称，汝、官、哥、钧、定五大名窑的作品至今仍备受藏家青睐。","由于该公司长期忽视产品质量与售后服务，令这个曾经风靡全国的品牌逐渐失去了消费者的信任。","人体的生物钟受下丘脑中一个微小区域的调控，长期熬夜会扰乱其节律，进而损害免疫功能。"],"a":2,"type":"주어 결여","why":"“由于……，令这个品牌……”에서 由于 구 뒤에 令이 와서 ‘失去了信任’의 주어가 없다.","fix":"由于该公司长期忽视产品质量与售后服务，这个曾经风靡全国的品牌逐渐失去了消费者的信任。","words":[["鉴于","jiànyú","~을 감안하여"],["釉色","yòusè","유약 빛깔"],["青睐","qīnglài","호감, 인기"],["风靡","fēngmǐ","풍미하다, 크게 유행하다"],["下丘脑","xiàqiūnǎo","시상하부"],["节律","jiélǜ","리듬"],["熬夜","áoyè","밤을 새우다"]],"tr":["일부 지역의 집세가 너무 빨리 오르자, 지방 정부는 새로 이주한 시민과 청년의 주거를 보장하기 위해 여러 조치를 내놓았다.","송나라 도자기는 유약 빛깔이 은은하고 모양이 간결하기로 유명하며, 여·관·가·균·정 5대 명요의 작품은 지금도 수집가들에게 큰 인기를 누린다.","이 회사가 오랫동안 품질과 애프터서비스를 소홀히 하는 바람에, 한때 전국을 휩쓸던 이 브랜드는 점점 소비자의 신뢰를 잃었다.","사람의 생체 시계는 시상하부의 아주 작은 부위가 조절하는데, 밤을 자주 새우면 그 리듬이 흐트러져 면역 기능까지 손상된다."],"ow":[[["鉴于","jiànyú","~을 감안하여"],["出台","chūtái","(정책을) 내놓다"],["一系列","yíxìliè","일련의"],["保障","bǎozhàng","보장하다"]],[["釉色","yòusè","유약 빛깔"],["温润","wēnrùn","은은하고 윤기 있다"],["简约","jiǎnyuē","간결하다"],["著称","zhùchēng","~로 유명하다"],["名窑","míngyáo","이름난 가마"],["青睐","qīnglài","호감, 인기"]],[["忽视","hūshì","소홀히 하다"],["售后服务","shòuhòu fúwù","애프터서비스"],["风靡","fēngmǐ","크게 유행하다"]],[["生物钟","shēngwùzhōng","생체 시계"],["下丘脑","xiàqiūnǎo","시상하부"],["调控","tiáokòng","조절하다"],["熬夜","áoyè","밤을 새우다"],["节律","jiélǜ","리듬"],["免疫","miǎnyì","면역"]]]},{"o":["都市圈的形成，使中心城市的产业和人口逐步向周边中小城市疏解，区域发展更加均衡。","京剧融合了唱、念、做、打等多种表演手段，被誉为中国的“国粹”。","物流行业的快速扩张为大量农村富余劳动力提供了就业机会，也带动了县域经济的发展。","在社区工作人员和志愿者的耐心劝导下，使许多老年人学会了用智能手机预约挂号和缴纳水电费。"],"a":3,"type":"주어 결여","why":"“在……下，使许多老年人学会了……”에서 在…下 뒤에 使가 와서 주어가 없다.","fix":"在社区工作人员和志愿者的耐心劝导下，许多老年人学会了用智能手机预约挂号和缴纳水电费。","words":[["都市圈","dūshìquān","대도시권"],["疏解","shūjiě","분산시키다"],["国粹","guócuì","나라의 정수"],["富余","fùyu","남아도는"],["县域","xiànyù","현 단위 지역"],["劝导","quàndǎo","타일러 이끌다"],["挂号","guàhào","(병원) 접수하다"]],"tr":["대도시권이 생기면서 중심 도시의 산업과 인구가 주변 중소도시로 점차 분산되어 지역 발전이 더 균형을 이루었다.","경극은 노래, 대사, 연기, 무술 등 여러 표현 방식을 아우르며 중국의 ‘국수(나라의 정수)’로 불린다.","물류 산업이 빠르게 커지면서 많은 농촌 유휴 인력에게 일자리가 생겼고, 현 지역 경제도 함께 성장했다.","지역사회 직원과 자원봉사자들이 끈기 있게 도와준 덕분에, 많은 노인이 스마트폰으로 병원 예약을 하고 수도·전기 요금을 내는 법을 배웠다."],"ow":[[["都市圈","dūshìquān","대도시권"],["疏解","shūjiě","분산시키다"],["均衡","jūnhéng","균형 잡히다"]],[["京剧","jīngjù","경극"],["融合","rónghé","융합하다"],["被誉为","bèi yù wéi","~로 칭송받다"],["国粹","guócuì","나라의 정수"]],[["扩张","kuòzhāng","확장"],["富余","fùyu","남아도는"],["劳动力","láodònglì","노동력"],["县域","xiànyù","현 단위 지역"]],[["志愿者","zhìyuànzhě","자원봉사자"],["劝导","quàndǎo","타일러 이끌다"],["挂号","guàhào","(병원) 접수하다"],["缴纳","jiǎonà","납부하다"]]]},{"o":["针对一些大城市早晚高峰地铁过度拥挤的问题，多地交通部门近年来通过错峰出行补贴和增开定制公交等一系列措施。","冰壶运动起源于十六世纪的苏格兰，比赛中队员用冰刷擦扫冰面，以调整冰壶的滑行距离和方向。","在线教育的兴起打破了优质教育资源的地域限制，但也对学生的自律能力提出了更高的要求。","研究表明，适度的音乐训练能够增强儿童大脑对声音的辨别能力，并在一定程度上提升其语言学习效率。"],"a":0,"type":"술어 결여","why":"“通过……等一系列措施”으로 끝나 交通部门이 무엇을 했는지 말하는 동사가 없다.","fix":"针对一些大城市早晚高峰地铁过度拥挤的问题，多地交通部门近年来推出了错峰出行补贴和增开定制公交等一系列措施。","words":[["错峰","cuòfēng","시간대를 분산하다"],["定制","dìngzhì","맞춤 제작하다"],["兴起","xīngqǐ","흥하기 시작하다"],["自律","zìlǜ","스스로 절제하다"],["辨别","biànbié","분별하다"],["冰壶","bīnghú","컬링"],["擦扫","cāsǎo","문질러 쓸다"]],"tr":["일부 대도시의 출퇴근 시간 지하철 혼잡 문제에 대해, 여러 지역 교통 당국은 최근 시차 출근 보조금과 맞춤형 버스 증편 같은 조치를 통해 대응하고 있다.","컬링은 16세기 스코틀랜드에서 시작되었으며, 경기 중 선수들은 빗자루로 얼음을 문질러 스톤이 미끄러지는 거리와 방향을 조절한다.","온라인 교육이 떠오르면서 좋은 교육 자원의 지역 제한은 깨졌지만, 학생의 자기 관리 능력에 대한 요구는 더 높아졌다.","연구에 따르면 적당한 음악 훈련은 아이 뇌의 소리 구별 능력을 키우고, 어느 정도 언어 학습 효율도 높여 준다."],"ow":[[["针对","zhēnduì","~에 대하여"],["拥挤","yōngjǐ","붐비다"],["错峰","cuòfēng","시간대를 분산하다"],["补贴","bǔtiē","보조금"],["定制","dìngzhì","맞춤 제작하다"]],[["冰壶","bīnghú","컬링"],["苏格兰","Sūgélán","스코틀랜드"],["擦扫","cāsǎo","문질러 쓸다"],["滑行","huáxíng","미끄러져 나아가다"]],[["兴起","xīngqǐ","흥하기 시작하다"],["优质","yōuzhì","질 좋은"],["地域","dìyù","지역"],["自律","zìlǜ","스스로 절제하다"]],[["适度","shìdù","적당하다"],["辨别","biànbié","분별하다"],["效率","xiàolǜ","효율"]]]},{"o":["苏州园林讲究移步换景，在有限的空间里营造出“虽由人作，宛自天开”的意境。","为了进一步激发农村消费潜力，有关部门今年将在全国范围内对家电、汽车等大宗商品的以旧换新。","大熊猫的祖先曾以食肉为主，后来在漫长的演化过程中才逐渐改为以竹子为食。","随着电商直播的火爆，一批农产品借助短视频平台走出大山，卖到了全国各地。"],"a":1,"type":"술어 결여","why":"“对……的以旧换新”으로 끝나 对 구 뒤에 와야 할 동사(给予补贴 등)가 없다.","fix":"为了进一步激发农村消费潜力，有关部门今年将在全国范围内对家电、汽车等大宗商品的以旧换新给予补贴。","words":[["激发","jīfā","불러일으키다"],["潜力","qiánlì","잠재력"],["大宗","dàzōng","대량의, 고가의"],["以旧换新","yǐ jiù huàn xīn","헌것을 새것으로 바꾸다"],["移步换景","yí bù huàn jǐng","걸음마다 경치가 바뀌다"],["意境","yìjìng","정취"],["演化","yǎnhuà","진화"]],"tr":["쑤저우 정원은 걸음마다 경치가 바뀌도록 꾸며, 좁은 공간에 ‘사람이 만들었으나 하늘이 빚은 듯한’ 정취를 자아낸다.","농촌 소비 잠재력을 더 끌어내기 위해, 관련 부처는 올해 전국에서 가전·자동차 같은 고가 상품의 보상 교체에 보조금을 줄 계획이다.","판다의 조상은 원래 주로 고기를 먹었는데, 오랜 진화 과정을 거치며 점차 대나무를 먹게 되었다.","라이브 커머스가 인기를 끌면서 많은 농산물이 짧은 영상 플랫폼을 타고 산골을 벗어나 전국으로 팔려 나갔다."],"ow":[[["苏州园林","Sūzhōu yuánlín","쑤저우 정원"],["移步换景","yí bù huàn jǐng","걸음마다 경치가 바뀌다"],["营造","yíngzào","만들어 내다"],["意境","yìjìng","정취"]],[["激发","jīfā","불러일으키다"],["潜力","qiánlì","잠재력"],["大宗","dàzōng","대량의, 고가의"],["以旧换新","yǐ jiù huàn xīn","헌것을 새것으로 바꾸다"]],[["祖先","zǔxiān","조상"],["漫长","màncháng","길고 긴"],["演化","yǎnhuà","진화"]],[["电商","diànshāng","전자상거래"],["火爆","huǒbào","대인기다"],["借助","jièzhù","힘을 빌리다"]]]},{"o":["李时珍历时二十七年，参考八百余种文献，编成了药物学巨著《本草纲目》。","消费者对绿色、健康产品的偏好日益明显，这促使不少食品企业调整了原有的生产线。","这份由多家研究机构联合发布的报告，关于近十年来我国城镇化进程中农业转移人口市民化的现状及其面临的主要障碍。","鹦鹉螺的外壳内部被分隔成数十个气室，它通过调节气室中的气体和液体来控制自身的浮沉。"],"a":2,"type":"술어 결여","why":"주어 ‘报告’ 뒤에 “关于……障碍”라는 개사구만 있고 술어 동사(分析了 등)가 없다.","fix":"这份由多家研究机构联合发布的报告，分析了近十年来我国城镇化进程中农业转移人口市民化的现状及其面临的主要障碍。","words":[["李时珍","Lǐ Shízhēn","이시진(명대 의학자)"],["本草纲目","Běncǎo Gāngmù","본초강목"],["偏好","piānhào","선호"],["促使","cùshǐ","~하도록 재촉하다"],["城镇化","chéngzhènhuà","도시화"],["鹦鹉螺","yīngwǔluó","앵무조개"],["浮沉","fúchén","뜨고 가라앉음"]],"tr":["이시진은 27년에 걸쳐 800여 종의 문헌을 참고해 약물학의 대작 『본초강목』을 펴냈다.","친환경·건강 제품을 찾는 소비자가 뚜렷이 늘자 많은 식품 기업이 기존 생산 라인을 바꾸었다.","여러 연구 기관이 함께 낸 이 보고서는 최근 10년간 우리나라 도시화 과정에서 농촌 이주 인구가 도시민이 되는 현황과 그 주요 걸림돌을 다룬다.","앵무조개의 껍데기 안은 수십 개의 공기방으로 나뉘어 있으며, 방 안의 기체와 액체를 조절해 뜨고 가라앉는다."],"ow":[[["李时珍","Lǐ Shízhēn","이시진"],["文献","wénxiàn","문헌"],["巨著","jùzhù","대작"],["本草纲目","Běncǎo Gāngmù","본초강목"]],[["偏好","piānhào","선호"],["日益","rìyì","날로"],["促使","cùshǐ","~하도록 만들다"]],[["城镇化","chéngzhènhuà","도시화"],["进程","jìnchéng","진행 과정"],["市民化","shìmínhuà","도시민화"],["障碍","zhàng'ài","장애"]],[["鹦鹉螺","yīngwǔluó","앵무조개"],["分隔","fēngé","나누다"],["调节","tiáojié","조절하다"],["浮沉","fúchén","뜨고 가라앉음"]]]},{"o":["侗族的鼓楼不用一钉一铆，全凭榫卯结构支撑，体现了高超的建筑技艺。","一些城市尝试将废弃的工业厂房改造成文化创意园区，既保留了历史记忆，又激活了周边经济。","每年秋季，数以万计的斑头雁从青藏高原起飞，飞越喜马拉雅山脉，前往印度等地越冬。","这家物流企业引入无人仓储和智能分拣系统后，大大缩短了包裹从入库到出库所需的。"],"a":3,"type":"목적어 결여","why":"“缩短了……所需的” 뒤에 꾸밈을 받는 명사 ‘时间’이 없다.","fix":"这家物流企业引入无人仓储和智能分拣系统后，大大缩短了包裹从入库到出库所需的时间。","words":[["仓储","cāngchǔ","창고 보관"],["分拣","fēnjiǎn","분류하다"],["侗族","Dòngzú","동족"],["榫卯","sǔnmǎo","장부 이음"],["废弃","fèiqì","버려진"],["激活","jīhuó","활성화하다"],["斑头雁","bāntóuyàn","줄기러기"],["喜马拉雅山脉","Xǐmǎlāyǎ Shānmài","히말라야산맥"]],"tr":["동족의 고루는 못 하나 쓰지 않고 장부 이음 구조만으로 지탱되어 뛰어난 건축 기술을 보여 준다.","일부 도시는 버려진 공장 건물을 문화 창작 단지로 바꾸어 역사의 기억을 남기는 동시에 주변 경제를 살려 냈다.","해마다 가을이면 수만 마리의 줄기러기가 칭짱고원을 떠나 히말라야산맥을 넘어 인도 등지에서 겨울을 난다.","이 물류 기업은 무인 창고와 스마트 분류 시스템을 들인 뒤 소포가 입고에서 출고까지 걸리는 시간을 크게 줄였다."],"ow":[[["侗族","Dòngzú","동족"],["鼓楼","gǔlóu","고루(북 누각)"],["榫卯","sǔnmǎo","장부 이음"],["支撑","zhīchēng","지탱하다"],["高超","gāochāo","뛰어나다"]],[["废弃","fèiqì","버려진"],["厂房","chǎngfáng","공장 건물"],["园区","yuánqū","단지"],["激活","jīhuó","활성화하다"]],[["数以万计","shù yǐ wàn jì","수만에 이르는"],["斑头雁","bāntóuyàn","줄기러기"],["青藏高原","Qīngzàng Gāoyuán","칭짱고원"],["喜马拉雅山脉","Xǐmǎlāyǎ Shānmài","히말라야산맥"],["越冬","yuèdōng","겨울을 나다"]],[["仓储","cāngchǔ","창고 보관"],["分拣","fēnjiǎn","분류하다"],["入库","rùkù","입고하다"]]]},{"o":["该市出台的人才新政，吸引了大批来自全国各地、拥有硕士以上学历并愿意扎根基层的。","踢毽子相传起源于汉代，因所需场地小、器材简单，至今仍深受中小学生喜爱。","由于人口持续向大城市集聚，一些偏远乡镇的中小学出现了生源不足的现象。","花样滑冰选手在高速旋转时收紧双臂，能利用角动量守恒原理使转速明显加快。"],"a":0,"type":"목적어 결여","why":"“吸引了大批……扎根基层的” 뒤에 목적어 중심 명사(青年人才 등)가 없다.","fix":"该市出台的人才新政，吸引了大批来自全国各地、拥有硕士以上学历并愿意扎根基层的青年人才。","words":[["扎根","zhāgēn","뿌리내리다"],["基层","jīcéng","현장, 말단 조직"],["集聚","jíjù","모여들다"],["生源","shēngyuán","입학생 자원"],["毽子","jiànzi","제기"],["器材","qìcái","기자재"],["角动量","jiǎodòngliàng","각운동량"],["守恒","shǒuhéng","보존되다"]],"tr":["이 시의 새 인재 정책은 전국 각지에서 석사 이상 학력을 갖추고 현장에 뿌리내리려는 젊은 인재를 대거 끌어들였다.","제기차기는 한나라 때 시작되었다고 전하며, 넓은 장소나 복잡한 도구가 필요 없어 지금도 초중고 학생들에게 인기가 많다.","인구가 계속 대도시로 몰리면서 일부 외딴 향진의 초중학교는 학생 수가 모자라는 현상을 겪고 있다.","피겨스케이팅 선수가 빠르게 돌 때 두 팔을 오므리면 각운동량 보존 원리로 회전 속도가 눈에 띄게 빨라진다."],"ow":[[["新政","xīnzhèng","새 정책"],["硕士","shuòshì","석사"],["扎根","zhāgēn","뿌리내리다"],["基层","jīcéng","현장, 말단 조직"]],[["毽子","jiànzi","제기"],["相传","xiāngchuán","~라고 전해지다"],["器材","qìcái","기자재"]],[["集聚","jíjù","모여들다"],["偏远","piānyuǎn","외지다"],["乡镇","xiāngzhèn","향진(읍면)"],["生源","shēngyuán","입학생 자원"]],[["花样滑冰","huāyàng huábīng","피겨스케이팅"],["角动量","jiǎodòngliàng","각운동량"],["守恒","shǒuhéng","보존되다"]]]},{"o":["《清明上河图》生动描绘了北宋都城汴京的繁华景象，是研究宋代社会生活的珍贵资料。","实践证明，发展县域特色产业，不仅能够增加农民收入，而且可以有效增强乡村对年轻人的。","一些互联网平台利用算法对老用户“杀熟”，这种行为损害了消费者的合法权益，理应受到监管。","竹子的生长速度极快，有的品种一天之内能长高将近一米，堪比植物界的“短跑冠军”。"],"a":1,"type":"목적어 결여","why":"“增强乡村对年轻人的” 뒤에 목적어 중심 명사 ‘吸引力’가 없다.","fix":"实践证明，发展县域特色产业，不仅能够增加农民收入，而且可以有效增强乡村对年轻人的吸引力。","words":[["清明上河图","Qīngmíng Shàng Hé Tú","청명상하도"],["汴京","Biànjīng","변경(북송 수도)"],["繁华","fánhuá","번화하다"],["算法","suànfǎ","알고리즘"],["杀熟","shāshú","단골에게 바가지 씌우기"],["理应","lǐyīng","마땅히 ~해야 한다"],["监管","jiānguǎn","감독 관리"]],"tr":["『청명상하도』는 북송의 수도 변경의 번화한 모습을 생생하게 그린 그림으로, 송나라 사회생활을 연구하는 귀한 자료다.","현 지역 특색 산업을 키우면 농민 소득이 늘 뿐 아니라 농촌이 젊은이를 끌어당기는 힘도 커진다는 것이 실제로 입증되었다.","일부 인터넷 플랫폼은 알고리즘으로 기존 고객에게 더 비싼 값을 매기는데, 이는 소비자의 정당한 권익을 해치므로 마땅히 감독을 받아야 한다.","대나무는 자라는 속도가 매우 빨라 어떤 품종은 하루에 1미터 가까이 자라므로 식물계의 ‘단거리 챔피언’이라 할 만하다."],"ow":[[["清明上河图","Qīngmíng Shàng Hé Tú","청명상하도"],["描绘","miáohuì","묘사하다"],["汴京","Biànjīng","변경(북송 수도)"],["繁华","fánhuá","번화하다"]],[["实践","shíjiàn","실천"],["县域","xiànyù","현 단위 지역"],["乡村","xiāngcūn","농촌"]],[["算法","suànfǎ","알고리즘"],["杀熟","shāshú","단골에게 바가지 씌우기"],["权益","quányì","권익"],["理应","lǐyīng","마땅히 ~해야 한다"],["监管","jiānguǎn","감독 관리"]],[["品种","pǐnzhǒng","품종"],["将近","jiāngjìn","거의"],["堪比","kānbǐ","~에 견줄 만하다"]]]}],[{"o":["明长城东起辽宁虎山，西至甘肃嘉峪关，是中国古代规模最宏大的军事防御工程。","越来越多的年轻人选择“断舍离”，减少不必要的消费，转而追求简约、实用的生活方式。","据统计，该市去年新增的城镇就业岗位约有十二万个左右，其中近一半来自数字经济领域。","研究表明，延迟性肌肉酸痛主要与肌纤维的细微损伤有关，通常在运动后一到两天达到高峰。"],"a":2,"type":"어림수 중복","why":"“约”와 “左右”는 둘 다 어림수를 나타내므로 함께 쓰면 뜻이 겹친다.","fix":"据统计，该市去年新增的城镇就业岗位约有十二万个，其中近一半来自数字经济领域。","words":[["嘉峪关","Jiāyù Guān","가욕관"],["防御","fángyù","방어"],["断舍离","duànshělí","단사리(버리고 비우기)"],["简约","jiǎnyuē","간결하다"],["延迟性","yánchíxìng","지연성"],["肌纤维","jīxiānwéi","근섬유"]],"tr":["명나라 장성은 동쪽 랴오닝 후산에서 서쪽 간쑤 자위관까지 이어지며, 중국 고대에서 가장 규모가 큰 군사 방어 시설이다.","점점 더 많은 젊은이가 ‘단사리’를 택해 쓸데없는 소비를 줄이고 간결하고 실용적인 삶을 추구한다.","통계에 따르면 이 시에서 지난해 새로 생긴 도시 일자리는 약 12만 개이며, 그중 절반 가까이가 디지털 경제 분야에서 나왔다.","연구에 따르면 지연성 근육통은 주로 근섬유의 미세한 손상과 관련이 있으며, 보통 운동 후 하루이틀 뒤에 가장 심하다."],"ow":[[["辽宁","Liáoníng","랴오닝"],["嘉峪关","Jiāyù Guān","자위관"],["宏大","hóngdà","웅대하다"],["防御","fángyù","방어"]],[["断舍离","duànshělí","단사리(버리고 비우기)"],["转而","zhuǎn'ér","방향을 바꾸어"],["简约","jiǎnyuē","간결하다"]],[["岗位","gǎngwèi","일자리"],["数字经济","shùzì jīngjì","디지털 경제"],["领域","lǐngyù","분야"]],[["延迟性","yánchíxìng","지연성"],["酸痛","suāntòng","쑤시고 아프다"],["肌纤维","jīxiānwéi","근섬유"],["损伤","sǔnshāng","손상"]]]},{"o":["近五年来，该省常住人口的城镇化率提高了将近十个百分点，县城成为吸纳农村人口的重要载体。","家庭小型化、少子化的趋势，正在深刻影响着住房、教育、养老等多个领域的消费结构。","古希腊数学家欧几里得所著的《几何原本》，对欧洲数学的发展产生了深远影响，曾被译成多种文字。","这座始建于北魏的悬空寺距今已有将近一千五百年左右的历史，至今仍保存完好。"],"a":3,"type":"어림수 중복","why":"“将近”과 “左右”가 함께 쓰여 어림수 표현이 겹친다.","fix":"这座始建于北魏的悬空寺距今已有将近一千五百年的历史，至今仍保存完好。","words":[["吸纳","xīnà","받아들이다"],["载体","zàitǐ","매개체, 그릇"],["少子化","shǎozǐhuà","저출생"],["欧几里得","Ōujǐlǐdé","유클리드"],["几何原本","Jǐhé Yuánběn","기하학 원론"],["北魏","Běi Wèi","북위"],["悬空寺","Xuánkōng Sì","현공사"]],"tr":["최근 5년 동안 이 성의 상주인구 도시화율은 10%포인트 가까이 올랐고, 현성은 농촌 인구를 받아들이는 중요한 그릇이 되었다.","가족이 작아지고 아이가 줄어드는 흐름이 주거·교육·노인 돌봄 등 여러 분야의 소비 구조에 깊은 영향을 주고 있다.","고대 그리스 수학자 유클리드가 쓴 『기하학 원론』은 유럽 수학 발전에 깊은 영향을 주었고, 여러 언어로 번역되었다.","북위 때 처음 지어진 이 현공사는 지은 지 1500년 가까이 되었는데도 지금까지 잘 보존되어 있다."],"ow":[[["常住人口","chángzhù rénkǒu","상주인구"],["城镇化率","chéngzhènhuàlǜ","도시화율"],["吸纳","xīnà","받아들이다"],["载体","zàitǐ","매개체, 그릇"]],[["少子化","shǎozǐhuà","저출생"],["趋势","qūshì","추세"],["养老","yǎnglǎo","노후 돌봄"]],[["欧几里得","Ōujǐlǐdé","유클리드"],["几何原本","Jǐhé Yuánběn","기하학 원론"],["深远","shēnyuǎn","깊고 크다"]],[["北魏","Běi Wèi","북위"],["悬空寺","Xuánkōng Sì","현공사"],["将近","jiāngjìn","거의"]]]},{"o":["这位老匠人毕生一辈子都在钻研景泰蓝的掐丝工艺，培养了数十名技艺精湛的弟子。","网约车的出现改变了人们的出行习惯，也给传统出租车行业带来了前所未有的冲击。","世界卫生组织建议，成年人每周至少进行一百五十分钟中等强度的有氧运动。","由于房价收入比长期偏高，部分一线城市的年轻人不得不推迟购房和成家的计划。"],"a":0,"type":"단어 안 뜻 반복","why":"“毕生”이 이미 ‘한평생’이라는 뜻이라 “一辈子”와 뜻이 겹친다.","fix":"这位老匠人毕生都在钻研景泰蓝的掐丝工艺，培养了数十名技艺精湛的弟子。","words":[["毕生","bìshēng","평생"],["钻研","zuānyán","깊이 연구하다"],["景泰蓝","jǐngtàilán","경태람(칠보 공예)"],["掐丝","qiāsī","금속 실 붙이기"],["精湛","jīngzhàn","뛰어나다"],["网约车","wǎngyuēchē","앱 호출 차량"],["前所未有","qián suǒ wèi yǒu","전례 없는"]],"tr":["이 노장인은 평생 경태람의 금속 실 붙이기 기법을 연구하며 솜씨 좋은 제자를 수십 명 길러 냈다.","앱 호출 차량이 나오면서 사람들의 이동 습관이 바뀌었고, 기존 택시 업계도 전례 없는 충격을 받았다.","세계보건기구는 성인이 일주일에 적어도 150분 이상 중간 강도의 유산소 운동을 하라고 권한다.","소득 대비 집값이 오랫동안 높았던 탓에, 일부 1선 도시의 젊은이들은 집 장만과 결혼 계획을 미룰 수밖에 없었다."],"ow":[[["毕生","bìshēng","평생"],["钻研","zuānyán","깊이 연구하다"],["景泰蓝","jǐngtàilán","경태람(칠보 공예)"],["掐丝","qiāsī","금속 실 붙이기"],["精湛","jīngzhàn","뛰어나다"]],[["网约车","wǎngyuēchē","앱 호출 차량"],["前所未有","qián suǒ wèi yǒu","전례 없는"],["冲击","chōngjī","충격"]],[["世界卫生组织","Shìjiè Wèishēng Zǔzhī","세계보건기구"],["强度","qiángdù","강도"],["有氧运动","yǒuyǎng yùndòng","유산소 운동"]],[["房价收入比","fángjià shōurù bǐ","소득 대비 집값 비율"],["偏高","piāngāo","높은 편이다"],["不得不","bùdébù","~할 수밖에 없다"]]]},{"o":["云冈石窟开凿于北魏时期，其雕刻艺术吸收了犍陀罗风格，同时融入了中原文化的特色。","不少城市推出夜间经济扶持政策，其目的是为了延长消费时间、拓展消费空间，从而拉动内需。","海水淡化技术的进步，为解决沿海缺水城市的用水难题提供了新的途径。","近年来，县城商业综合体如雨后春笋般涌现，成为当地居民休闲购物的新去处。"],"a":1,"type":"단어 안 뜻 반복","why":"“目的”과 “为了”가 둘 다 목적을 나타내 “目的是为了”는 뜻이 겹친다.","fix":"不少城市推出夜间经济扶持政策，其目的是延长消费时间、拓展消费空间，从而拉动内需。","words":[["云冈石窟","Yúngāng Shíkū","운강 석굴"],["开凿","kāizáo","파서 만들다"],["犍陀罗","Gāntuóluó","간다라"],["扶持","fúchí","지원하다"],["拓展","tuòzhǎn","넓히다"],["内需","nèixū","내수"],["淡化","dànhuà","담수화"],["雨后春笋","yǔ hòu chūn sǔn","우후죽순"]],"tr":["운강 석굴은 북위 때 파서 만들었으며, 그 조각 예술은 간다라 양식을 받아들이는 동시에 중원 문화의 특색을 담았다.","많은 도시가 야간 경제 지원 정책을 내놓았는데, 그 목적은 소비 시간을 늘리고 소비 공간을 넓혀 내수를 끌어올리는 것이다.","바닷물 담수화 기술의 발전은 물이 부족한 해안 도시의 용수 문제를 풀 새로운 길을 열어 주었다.","최근 현성에는 대형 복합 상업 시설이 우후죽순처럼 생겨나 주민들의 새로운 쇼핑·여가 장소가 되었다."],"ow":[[["云冈石窟","Yúngāng Shíkū","운강 석굴"],["开凿","kāizáo","파서 만들다"],["犍陀罗","Gāntuóluó","간다라"],["中原","Zhōngyuán","중원"]],[["扶持","fúchí","지원하다"],["拓展","tuòzhǎn","넓히다"],["拉动","lādòng","끌어올리다"],["内需","nèixū","내수"]],[["淡化","dànhuà","담수화"],["沿海","yánhǎi","연해"],["途径","tújìng","방법, 경로"]],[["综合体","zōnghétǐ","복합 시설"],["雨后春笋","yǔ hòu chūn sǔn","우후죽순"],["涌现","yǒngxiàn","한꺼번에 나타나다"]]]},{"o":["被誉为“天下第一行书”的《兰亭集序》，出自东晋书法家王羲之之手。","城市更新不应简单地大拆大建，而应注重保护街区原有的肌理与烟火气。","部分商家在促销活动中设置的满减规则过于太复杂，不少消费者反映难以算清实际优惠。","北极熊皮下厚厚的脂肪层可以帮助它们在零下几十摄氏度的严寒中保持体温。"],"a":2,"type":"단어 안 뜻 반복","why":"“过于”가 이미 ‘지나치게’라는 뜻이라 “太”와 겹친다.","fix":"部分商家在促销活动中设置的满减规则过于复杂，不少消费者反映难以算清实际优惠。","words":[["兰亭集序","Lántíng Jí Xù","난정집서"],["王羲之","Wáng Xīzhī","왕희지"],["肌理","jīlǐ","결, 짜임"],["烟火气","yānhuǒqì","사람 사는 냄새"],["满减","mǎnjiǎn","일정 금액 이상 할인"],["脂肪","zhīfáng","지방"],["摄氏度","shèshìdù","섭씨 온도"]],"tr":["‘천하제일 행서’로 불리는 『난정집서』는 동진의 서예가 왕희지가 쓴 작품이다.","도시 재생은 단순히 크게 허물고 크게 짓는 것이 아니라, 거리 본래의 결과 사람 사는 냄새를 지키는 데 힘써야 한다.","일부 상점이 할인 행사에서 정한 금액별 할인 규칙이 너무 복잡해서, 많은 소비자가 실제 할인액을 계산하기 어렵다고 말한다.","북극곰 피부 아래의 두꺼운 지방층은 영하 수십 도의 혹한에서도 체온을 지키게 해 준다."],"ow":[[["被誉为","bèi yù wéi","~로 칭송받다"],["行书","xíngshū","행서"],["兰亭集序","Lántíng Jí Xù","난정집서"],["王羲之","Wáng Xīzhī","왕희지"]],[["城市更新","chéngshì gēngxīn","도시 재생"],["肌理","jīlǐ","결, 짜임"],["烟火气","yānhuǒqì","사람 사는 냄새"]],[["促销","cùxiāo","판촉"],["满减","mǎnjiǎn","일정 금액 이상 할인"],["过于","guòyú","지나치게"]],[["脂肪","zhīfáng","지방"],["摄氏度","shèshìdù","섭씨 온도"],["严寒","yánhán","혹한"]]]},{"o":["外卖行业的蓬勃发展催生了大量骑手岗位，但这一群体的社会保障问题也随之凸显出来。","西藏布达拉宫依山而建，宫墙层层叠叠，是藏族古代建筑艺术的杰出代表。","尽管线上购物日益便捷，实体书店仍凭借独特的阅读氛围和文化活动吸引着一批忠实读者。","医学专家提醒，过度滥用抗生素会使细菌产生耐药性，导致原本有效的药物逐渐失效。"],"a":3,"type":"단어 안 뜻 반복","why":"“滥用”에 이미 ‘지나치게 쓰다’는 뜻이 있어 “过度”와 겹친다.","fix":"医学专家提醒，滥用抗生素会使细菌产生耐药性，导致原本有效的药物逐渐失效。","words":[["蓬勃","péngbó","왕성하다"],["催生","cuīshēng","생겨나게 하다"],["凸显","tūxiǎn","두드러지다"],["布达拉宫","Bùdálā Gōng","포탈라궁"],["滥用","lànyòng","남용하다"],["抗生素","kàngshēngsù","항생제"],["耐药性","nàiyàoxìng","약물 내성"]],"tr":["배달 산업이 크게 성장하면서 배달원 일자리가 대량으로 생겨났지만, 이들의 사회 보장 문제도 함께 두드러졌다.","티베트의 포탈라궁은 산을 따라 지어져 궁의 담이 겹겹이 이어지며, 티베트족 고대 건축 예술의 대표작이다.","온라인 쇼핑이 날로 편리해졌지만, 동네 서점은 특유의 독서 분위기와 문화 행사로 여전히 충성 독자들을 끌어모으고 있다.","의학 전문가들은 항생제를 지나치게 남용하면 세균에 내성이 생겨 원래 잘 듣던 약도 점점 효과가 없어진다고 경고한다."],"ow":[[["蓬勃","péngbó","왕성하다"],["催生","cuīshēng","생겨나게 하다"],["骑手","qíshǒu","배달 기사"],["凸显","tūxiǎn","두드러지다"]],[["西藏","Xīzàng","티베트"],["布达拉宫","Bùdálā Gōng","포탈라궁"],["层层叠叠","céngcéng diédié","겹겹이"],["杰出","jiéchū","걸출하다"]],[["尽管","jǐnguǎn","비록 ~하지만"],["氛围","fēnwéi","분위기"],["凭借","píngjiè","~에 힘입어"],["忠实","zhōngshí","충실한"]],[["滥用","lànyòng","남용하다"],["抗生素","kàngshēngsù","항생제"],["耐药性","nàiyàoxìng","약물 내성"],["失效","shīxiào","효력을 잃다"]]]},{"o":["一座城市能否吸引并留住年轻人才与否，很大程度上取决于其产业结构和公共服务水平。","古代丝绸之路不仅是商品贸易的通道，也是东西方宗教、艺术和科技交流的桥梁。","中国的人均国内生产总值已连续多年超过一万美元，消费对经济增长的贡献率稳步提升。","啄木鸟的舌头细长而富有弹性，末端长有倒钩，能轻易钩出藏在树干深处的害虫。"],"a":0,"type":"기타 군더더기","why":"“能否”에 이미 ‘할 수 있는지 없는지’ 두 면이 들어 있어 끝의 “与否”가 군더더기다.","fix":"一座城市能否吸引并留住年轻人才，很大程度上取决于其产业结构和公共服务水平。","words":[["丝绸之路","Sīchóu zhī Lù","실크로드"],["贡献率","gòngxiànlǜ","기여율"],["稳步","wěnbù","안정적으로"],["啄木鸟","zhuómùniǎo","딱따구리"],["弹性","tánxìng","탄력"],["倒钩","dàogōu","거꾸로 난 갈고리"]],"tr":["한 도시가 젊은 인재를 끌어들이고 붙잡아 둘 수 있는지는 대체로 그 도시의 산업 구조와 공공 서비스 수준에 달려 있다.","고대 실크로드는 상품 무역의 통로였을 뿐 아니라 동서양의 종교·예술·과학 교류의 다리이기도 했다.","중국의 1인당 국내총생산은 여러 해 연속 1만 달러를 넘었고, 경제 성장에 대한 소비의 기여율도 꾸준히 오르고 있다.","딱따구리의 혀는 가늘고 길며 탄력이 있고 끝에 거꾸로 난 갈고리가 있어 나무줄기 깊숙이 숨은 해충을 쉽게 꺼낸다."],"ow":[[["能否","néngfǒu","~할 수 있는지"],["与否","yǔfǒu","~인지 아닌지"],["取决于","qǔjué yú","~에 달려 있다"]],[["丝绸之路","Sīchóu zhī Lù","실크로드"],["通道","tōngdào","통로"],["宗教","zōngjiào","종교"]],[["国内生产总值","guónèi shēngchǎn zǒngzhí","국내총생산"],["贡献率","gòngxiànlǜ","기여율"],["稳步","wěnbù","안정적으로"]],[["啄木鸟","zhuómùniǎo","딱따구리"],["弹性","tánxìng","탄력"],["倒钩","dàogōu","거꾸로 난 갈고리"],["害虫","hàichóng","해충"]]]},{"o":["都江堰水利工程由战国时期秦国蜀郡太守李冰主持修建，两千多年来一直发挥着防洪灌溉的作用。","近年来国产新能源汽车销量大增的主要原因，是因为电池技术取得突破，充电设施也日益完善。","人工智能在医学影像诊断中的应用，使早期肿瘤的检出率得到了显著提高。","一些乡村通过发展民宿和农家乐，把绿水青山转化为实实在在的经济收益。"],"a":1,"type":"기타 군더더기","why":"“原因是”와 “因为”가 둘 다 이유를 나타내 “原因，是因为”는 뜻이 겹친다.","fix":"近年来国产新能源汽车销量大增的主要原因，是电池技术取得突破，充电设施也日益完善。","words":[["都江堰","Dūjiāngyàn","도강언"],["蜀郡","Shǔ Jùn","촉군"],["太守","tàishǒu","태수"],["灌溉","guàngài","관개"],["影像","yǐngxiàng","영상"],["肿瘤","zhǒngliú","종양"],["民宿","mínsù","민박"]],"tr":["도강언 수리 시설은 전국 시대 진나라 촉군 태수 이빙이 주도해 만들었으며, 2천여 년 동안 홍수 방지와 관개 역할을 해 왔다.","최근 국산 신에너지차 판매가 크게 늘어난 주된 이유는 배터리 기술이 돌파구를 찾고 충전 시설도 날로 갖춰졌기 때문이다.","인공지능을 의료 영상 진단에 쓰면서 초기 종양을 찾아내는 비율이 크게 높아졌다.","일부 농촌은 민박과 농가 체험 관광을 키워 푸른 산과 맑은 물을 실질적인 경제 수익으로 바꾸었다."],"ow":[[["都江堰","Dūjiāngyàn","도강언"],["蜀郡","Shǔ Jùn","촉군"],["太守","tàishǒu","태수"],["李冰","Lǐ Bīng","이빙"],["灌溉","guàngài","관개"]],[["新能源汽车","xīn néngyuán qìchē","신에너지차"],["突破","tūpò","돌파"],["充电","chōngdiàn","충전"]],[["人工智能","réngōng zhìnéng","인공지능"],["影像","yǐngxiàng","영상"],["诊断","zhěnduàn","진단"],["肿瘤","zhǒngliú","종양"]],[["民宿","mínsù","민박"],["农家乐","nóngjiālè","농가 체험 관광"],["实实在在","shíshí zàizài","실질적인"]]]},{"o":["被列为国家一级保护动物的朱鹮，曾一度被认为已经灭绝，直到1981年才在陕西洋县重新被发现。","不少企业开始尝试灵活办公，让员工能够更好地兼顾工作与家庭。","个人所得税专项附加扣除政策的实施，使得让许多工薪家庭在子女教育和赡养老人方面的负担有所减轻。","唐代诗人杜甫的诗歌深刻反映了安史之乱前后的社会现实，因而被后人称为“诗史”。"],"a":2,"type":"기타 군더더기","why":"“使得”와 “让”이 둘 다 ‘~하게 하다’라는 뜻이라 하나가 군더더기다.","fix":"个人所得税专项附加扣除政策的实施，使许多工薪家庭在子女教育和赡养老人方面的负担有所减轻。","words":[["朱鹮","zhūhuán","따오기"],["灭绝","mièjué","멸종하다"],["兼顾","jiāngù","함께 돌보다"],["扣除","kòuchú","공제하다"],["赡养","shànyǎng","부양하다"],["安史之乱","Ān Shǐ zhī Luàn","안사의 난"],["诗史","shīshǐ","시로 쓴 역사"]],"tr":["국가 1급 보호 동물인 따오기는 한때 멸종한 줄 알았으나, 1981년에야 산시성 양현에서 다시 발견되었다.","많은 기업이 유연 근무를 시도하기 시작해 직원들이 일과 가정을 함께 더 잘 챙길 수 있게 했다.","개인소득세 특별 추가 공제 정책이 시행되면서 많은 월급 생활자 가정의 자녀 교육과 부모 부양 부담이 줄었다.","당나라 시인 두보의 시는 안사의 난 전후의 사회 현실을 깊이 담아 내어 후대 사람들에게 ‘시로 쓴 역사’라 불렸다."],"ow":[[["朱鹮","zhūhuán","따오기"],["一度","yídù","한때"],["灭绝","mièjué","멸종하다"],["洋县","Yáng Xiàn","양현(지명)"]],[["灵活","línghuó","유연하다"],["兼顾","jiāngù","함께 돌보다"]],[["所得税","suǒdéshuì","소득세"],["扣除","kòuchú","공제하다"],["工薪","gōngxīn","월급 생활자"],["赡养","shànyǎng","부양하다"]],[["杜甫","Dù Fǔ","두보"],["安史之乱","Ān Shǐ zhī Luàn","안사의 난"],["诗史","shīshǐ","시로 쓴 역사"]]]},{"o":["明代郑和七下西洋，船队最远到达了非洲东海岸，比哥伦布发现美洲大陆早了八十多年。","适量摄入膳食纤维有助于促进肠道蠕动，降低患某些慢性疾病的风险。","随着城市轨道交通网络的不断加密，“通勤圈”的范围正在向周边城市延伸。","凡是在本市连续缴纳社保满两年的外地户籍人员，均都可以申请购买共有产权住房。"],"a":3,"type":"기타 군더더기","why":"“均”과 “都”가 둘 다 ‘모두’라는 뜻이라 함께 쓰면 겹친다.","fix":"凡是在本市连续缴纳社保满两年的外地户籍人员，都可以申请购买共有产权住房。","words":[["郑和","Zhèng Hé","정화"],["哥伦布","Gēlúnbù","콜럼버스"],["膳食纤维","shànshí xiānwéi","식이섬유"],["蠕动","rúdòng","연동 운동"],["通勤","tōngqín","통근"],["缴纳","jiǎonà","납부하다"],["户籍","hùjí","호적"],["共有产权","gòngyǒu chǎnquán","공동 소유권"]],"tr":["명나라 정화는 일곱 차례 서양으로 항해해 함대가 멀리 아프리카 동해안까지 이르렀으며, 이는 콜럼버스가 아메리카 대륙을 발견한 것보다 80여 년 앞선다.","식이섬유를 알맞게 섭취하면 장 운동을 돕고 일부 만성 질환에 걸릴 위험을 낮출 수 있다.","도시철도망이 계속 촘촘해지면서 ‘통근권’이 주변 도시까지 넓어지고 있다.","이 시에서 2년 연속 사회보험료를 낸 외지 호적자는 누구나 공동 소유권 주택 구입을 신청할 수 있다."],"ow":[[["郑和","Zhèng Hé","정화"],["西洋","Xīyáng","서양(남해 서쪽 바다)"],["船队","chuánduì","함대"],["哥伦布","Gēlúnbù","콜럼버스"]],[["摄入","shèrù","섭취하다"],["膳食纤维","shànshí xiānwéi","식이섬유"],["蠕动","rúdòng","연동 운동"],["慢性","mànxìng","만성"]],[["轨道交通","guǐdào jiāotōng","도시철도"],["加密","jiāmì","촘촘하게 하다"],["通勤","tōngqín","통근"],["延伸","yánshēn","뻗어 나가다"]],[["凡是","fánshì","무릇 모든"],["缴纳","jiǎonà","납부하다"],["户籍","hùjí","호적"],["共有产权","gòngyǒu chǎnquán","공동 소유권"]]]}],[{"o":["青花瓷以钴料在瓷胎上绘制纹饰，再罩上透明釉高温烧成，元代时工艺已相当成熟。","为了吸引更多年轻消费者，这家老牌连锁超市对全国门店进行了升级改造，大大提高了顾客的购物环境。","低空经济的崛起，为无人机物流、空中观光等新业态的发展打开了广阔的空间。","科学家发现，长期处于噪声环境中的人更容易出现焦虑、失眠等症状。"],"a":1,"type":"동사–목적어","why":"“提高”는 “环境”과 어울리지 않는다. 환경은 “改善”한다.","fix":"为了吸引更多年轻消费者，这家老牌连锁超市对全国门店进行了升级改造，大大改善了顾客的购物环境。","words":[["青花瓷","qīnghuācí","청화백자"],["钴","gǔ","코발트"],["纹饰","wénshì","무늬"],["釉","yòu","유약"],["崛起","juéqǐ","떠오르다"],["业态","yètài","사업 형태"],["焦虑","jiāolǜ","초조함, 불안"]],"tr":["청화자기는 코발트 안료로 도자기 몸체에 무늬를 그린 뒤 투명 유약을 입혀 높은 온도로 구워 내며, 원나라 때 이미 기술이 꽤 무르익었다.","젊은 소비자를 더 끌어들이려고 이 오래된 체인 마트는 전국 매장을 새로 고쳐 고객의 쇼핑 환경을 크게 개선하려 했다.","저고도 경제가 떠오르면서 드론 물류, 공중 관광 같은 새로운 사업 형태가 발전할 넓은 공간이 열렸다.","과학자들은 오랫동안 소음 속에 사는 사람이 불안, 불면 같은 증상을 더 쉽게 겪는다는 것을 발견했다."],"ow":[[["青花瓷","qīnghuācí","청화백자"],["钴","gǔ","코발트"],["纹饰","wénshì","무늬"],["釉","yòu","유약"]],[["老牌","lǎopái","오래된 브랜드"],["连锁","liánsuǒ","체인"],["升级","shēngjí","업그레이드하다"]],[["低空经济","dīkōng jīngjì","저고도 경제"],["崛起","juéqǐ","떠오르다"],["无人机","wúrénjī","드론"],["业态","yètài","사업 형태"]],[["噪声","zàoshēng","소음"],["焦虑","jiāolǜ","초조함, 불안"],["失眠","shīmián","불면"],["症状","zhèngzhuàng","증상"]]]},{"o":["近年来，各地纷纷出台政策，积极培育消费新场景，努力满足居民日益多样化的消费水平。","自行车运动员在骑行时采用低头弓背的姿势，可以有效减小迎面而来的空气阻力。","冬季大气层结构稳定、风力较弱，污染物不易扩散，雾霾天气因而较为频繁。","一些跨国公司把研发中心设在中国，看中的不仅是庞大的市场，还有丰富的工程师资源。"],"a":0,"type":"동사–목적어","why":"“满足”는 “水平”과 어울리지 않는다. “需求”를 만족시킨다고 해야 한다.","fix":"近年来，各地纷纷出台政策，积极培育消费新场景，努力满足居民日益多样化的消费需求。","words":[["培育","péiyù","육성하다"],["扩散","kuòsàn","퍼지다"],["雾霾","wùmái","스모그"],["庞大","pángdà","방대하다"],["弓背","gōngbèi","등을 구부리다"],["阻力","zǔlì","저항"]],"tr":["최근 각 지역은 잇따라 정책을 내놓아 새로운 소비 장면을 적극 키우고, 날로 다양해지는 주민의 소비 수요를 채우려 애쓰고 있다.","자전거 선수가 고개를 숙이고 등을 구부린 자세로 달리면 정면에서 오는 공기 저항을 효과적으로 줄일 수 있다.","겨울에는 대기층이 안정되고 바람이 약해 오염 물질이 잘 퍼지지 않으므로 스모그가 비교적 잦다.","일부 다국적 기업이 연구 개발 센터를 중국에 두는 것은 거대한 시장뿐 아니라 풍부한 엔지니어 인력을 보았기 때문이다."],"ow":[[["纷纷","fēnfēn","잇따라"],["培育","péiyù","육성하다"],["场景","chǎngjǐng","장면"]],[["骑行","qíxíng","자전거를 타다"],["弓背","gōngbèi","등을 구부리다"],["迎面","yíngmiàn","정면으로"],["阻力","zǔlì","저항"]],[["大气层","dàqìcéng","대기층"],["扩散","kuòsàn","퍼지다"],["雾霾","wùmái","스모그"],["频繁","pínfán","잦다"]],[["跨国","kuàguó","다국적"],["研发","yánfā","연구 개발"],["庞大","pángdà","방대하다"]]]},{"o":["战国时期，诸子百家争鸣，儒、道、墨、法等学派的思想相互碰撞，深刻影响了后世。","由于缺乏天敌，入侵物种在新环境中往往迅速繁衍，对本地生态系统造成严重威胁。","高铁网络的延伸缩短了城市之间的时空距离，加速了人才、资金和技术等要素的流动。","该市举办的国际消费季活动吸引了大量外地游客，大大促进了本地餐饮、住宿等行业的营业额。"],"a":3,"type":"동사–목적어","why":"“促进”는 “营业额”와 어울리지 않는다. 매출액은 “增加”하거나 “提高”한다.","fix":"该市举办的国际消费季活动吸引了大量外地游客，大大增加了本地餐饮、住宿等行业的营业额。","words":[["诸子百家","zhūzǐ bǎijiā","제자백가"],["争鸣","zhēngmíng","논쟁하다"],["碰撞","pèngzhuàng","부딪치다"],["天敌","tiāndí","천적"],["繁衍","fányǎn","번식하다"],["要素","yàosù","요소"],["营业额","yíngyè'é","매출액"]],"tr":["전국 시대에는 제자백가가 다투어 주장을 펼쳤고, 유가·도가·묵가·법가 등의 사상이 서로 부딪치며 후대에 깊은 영향을 주었다.","천적이 없어서 외래 침입종은 새 환경에서 빠르게 번식하는 경우가 많고, 토착 생태계에 심각한 위협이 된다.","고속철도망이 뻗어 나가면서 도시 사이의 시간·공간 거리가 줄었고, 인재·자금·기술 같은 요소의 흐름이 빨라졌다.","이 시가 연 국제 소비 시즌 행사에 외지 관광객이 많이 몰려, 이 지역 음식·숙박 업계의 매출이 크게 늘었다."],"ow":[[["诸子百家","zhūzǐ bǎijiā","제자백가"],["争鸣","zhēngmíng","논쟁하다"],["学派","xuépài","학파"],["碰撞","pèngzhuàng","부딪치다"]],[["天敌","tiāndí","천적"],["入侵物种","rùqīn wùzhǒng","외래 침입종"],["繁衍","fányǎn","번식하다"],["威胁","wēixié","위협"]],[["高铁","gāotiě","고속철도"],["延伸","yánshēn","뻗어 나가다"],["要素","yàosù","요소"]],[["消费季","xiāofèijì","소비 시즌"],["餐饮","cānyǐn","요식업"],["住宿","zhùsù","숙박"],["营业额","yíngyè'é","매출액"]]]},{"o":["西湖的美不仅在于湖光山色，更在于历代文人墨客为它留下的诗词与传说。","实验表明，睡眠不足会削弱大脑对负面情绪的调节能力。","上海是全国最大的经济中心之一，其中心城区的人口密度十分拥挤，部分功能正逐步向郊区新城转移。","共享经济模式让闲置资源得到了充分利用，也带来了许多新的就业形态。"],"a":2,"type":"주어–술어","why":"주어 “人口密度”는 술어 “拥挤”와 어울리지 않는다. 밀도는 “很大”라고 해야 한다.","fix":"上海是全国最大的经济中心之一，其中心城区的人口密度很大，部分功能正逐步向郊区新城转移。","words":[["湖光山色","hú guāng shān sè","호수와 산의 경치"],["文人墨客","wénrén mòkè","문인과 묵객"],["削弱","xuēruò","약화시키다"],["负面","fùmiàn","부정적인"],["密度","mìdù","밀도"],["闲置","xiánzhì","놀리다, 방치하다"]],"tr":["시후의 아름다움은 호수와 산의 경치뿐 아니라, 역대 문인들이 남긴 시와 전설에 있다.","실험에 따르면 잠이 부족하면 부정적인 감정을 조절하는 뇌의 능력이 약해진다.","상하이는 전국 최대 경제 중심 가운데 하나로, 도심의 인구 밀도가 매우 높아 일부 기능을 교외 신도시로 차츰 옮기고 있다.","공유 경제는 놀고 있던 자원을 충분히 활용하게 했고, 새로운 고용 형태도 많이 만들어 냈다."],"ow":[[["西湖","Xī Hú","시후"],["湖光山色","hú guāng shān sè","호수와 산의 경치"],["文人墨客","wénrén mòkè","문인과 묵객"]],[["削弱","xuēruò","약화시키다"],["负面","fùmiàn","부정적인"],["调节","tiáojié","조절하다"]],[["密度","mìdù","밀도"],["拥挤","yōngjǐ","붐비다"],["郊区","jiāoqū","교외"]],[["共享经济","gòngxiǎng jīngjì","공유 경제"],["闲置","xiánzhì","놀리다, 방치하다"],["形态","xíngtài","형태"]]]},{"o":["拔河曾是早期现代奥运会的正式比赛项目，从1900年到1920年先后出现在五届奥运会上。","经过十余年的深耕，这家国产运动品牌的知名度在年轻消费者中已经家喻户晓。","研究人员发现，章鱼拥有发达的神经系统，能够模仿周围环境的颜色和纹理来躲避捕食者。","当地把废旧的仓库改造成了创业孵化基地，吸引了上百家初创企业入驻。"],"a":1,"type":"주어–술어","why":"주어 “知名度”는 “家喻户晓”(집집마다 다 안다)와 어울리지 않는다. 브랜드가 家喻户晓하거나 知名度가 높다고 해야 한다.","fix":"经过十余年的深耕，这家国产运动品牌在年轻消费者中已经家喻户晓。","words":[["深耕","shēngēng","깊이 파고들다"],["家喻户晓","jiā yù hù xiǎo","누구나 다 알다"],["章鱼","zhāngyú","문어"],["纹理","wénlǐ","무늬, 결"],["孵化","fūhuà","인큐베이팅"],["入驻","rùzhù","입주하다"],["拔河","báhé","줄다리기"]],"tr":["줄다리기는 초기 근대 올림픽의 정식 종목이었으며, 1900년부터 1920년까지 다섯 차례 올림픽에 나왔다.","십여 년간 깊이 공을 들인 끝에, 이 국산 스포츠 브랜드는 젊은 소비자 사이에서 누구나 아는 이름이 되었다.","연구진은 문어가 발달한 신경계를 갖고 있어 주변 환경의 색과 무늬를 흉내 내 포식자를 피할 수 있다는 것을 발견했다.","그 지역은 낡은 창고를 창업 인큐베이팅 기지로 바꾸어 백여 개의 신생 기업을 입주시켰다."],"ow":[[["拔河","báhé","줄다리기"],["奥运会","Àoyùnhuì","올림픽"],["先后","xiānhòu","차례로"]],[["深耕","shēngēng","깊이 파고들다"],["知名度","zhīmíngdù","인지도"],["家喻户晓","jiā yù hù xiǎo","누구나 다 알다"]],[["章鱼","zhāngyú","문어"],["神经系统","shénjīng xìtǒng","신경계"],["纹理","wénlǐ","무늬, 결"],["捕食者","bǔshízhě","포식자"]],[["废旧","fèijiù","낡고 오래된"],["孵化","fūhuà","인큐베이팅"],["初创","chūchuàng","창업 초기의"],["入驻","rùzhù","입주하다"]]]},{"o":["宁波最突出的发展优势，是一座拥有天然深水良港、外贸历史悠久的沿海城市。","马王堆汉墓的发掘，为研究西汉初期的丝织、漆器和医学提供了大量第一手资料。","居民收入的稳步增长，是消费市场保持活力的根本前提。","许多候鸟依靠地球磁场来确定方向，即便在阴天也不会迷失航线。"],"a":0,"type":"주어–목적어","why":"“优势是……城市”는 주어(장점)와 목적어(도시)가 어울리지 않는다.","fix":"宁波最突出的发展优势，是拥有天然深水良港和悠久的外贸历史。","words":[["深水良港","shēnshuǐ liánggǎng","수심 깊은 좋은 항구"],["外贸","wàimào","대외 무역"],["马王堆","Mǎwángduī","마왕퇴"],["丝织","sīzhī","견직"],["漆器","qīqì","칠기"],["候鸟","hòuniǎo","철새"],["磁场","cíchǎng","자기장"]],"tr":["닝보가 가진 가장 두드러진 발전 강점은 천연 심해 항구가 있고 대외 무역의 역사가 오래된 해안 도시라는 점이다.","마왕퇴 한나라 무덤의 발굴은 서한 초기의 견직, 칠기, 의학을 연구하는 데 많은 1차 자료를 주었다.","주민 소득의 꾸준한 증가는 소비 시장이 활력을 유지하는 근본 전제다.","많은 철새는 지구 자기장으로 방향을 잡기 때문에 흐린 날에도 길을 잃지 않는다."],"ow":[[["宁波","Níngbō","닝보"],["深水良港","shēnshuǐ liánggǎng","수심 깊은 좋은 항구"],["外贸","wàimào","대외 무역"],["悠久","yōujiǔ","유구하다"]],[["马王堆","Mǎwángduī","마왕퇴"],["发掘","fājué","발굴하다"],["丝织","sīzhī","견직"],["漆器","qīqì","칠기"]],[["稳步","wěnbù","안정적으로"],["活力","huólì","활력"],["前提","qiántí","전제"]],[["候鸟","hòuniǎo","철새"],["磁场","cíchǎng","자기장"],["即便","jíbiàn","설령 ~하더라도"],["航线","hángxiàn","비행 경로"]]]},{"o":["门球是在槌球的基础上改编而成的，因运动量适中、规则简单，在老年人中十分流行。","一个城市的公共交通是否便捷，直接关系到市民通勤的时间成本和生活质量。","人体约百分之六十由水组成，即使轻度脱水也可能导致注意力下降和疲劳。","这部纪录片的主人公，是一个关于外来务工人员在大城市打拼十余年、最终安家落户的真实故事。"],"a":3,"type":"주어–목적어","why":"“主人公是……故事”는 주어(주인공, 사람)와 목적어(이야기)가 어울리지 않는다.","fix":"这部纪录片讲述的，是一个关于外来务工人员在大城市打拼十余年、最终安家落户的真实故事。","words":[["脱水","tuōshuǐ","탈수"],["纪录片","jìlùpiàn","다큐멘터리"],["打拼","dǎpīn","분투하다"],["安家落户","ānjiā luòhù","정착하다"],["门球","ménqiú","게이트볼"],["槌球","chuíqiú","크로케"]],"tr":["게이트볼은 크로케를 바탕으로 고쳐 만든 운동으로, 운동량이 알맞고 규칙이 간단해 노인들 사이에서 인기가 많다.","한 도시의 대중교통이 편리한지는 시민의 통근 시간 비용과 삶의 질에 바로 영향을 준다.","사람 몸은 약 60%가 물로 이루어져 있어 가벼운 탈수만으로도 집중력이 떨어지고 피로해질 수 있다.","이 다큐멘터리는 외지 출신 노동자가 대도시에서 십여 년을 분투한 끝에 정착하는 실제 이야기를 담고 있다."],"ow":[[["门球","ménqiú","게이트볼"],["槌球","chuíqiú","크로케"],["改编","gǎibiān","고쳐 만들다"],["适中","shìzhōng","알맞다"]],[["是否","shìfǒu","~인지 아닌지"],["便捷","biànjié","편리하다"],["通勤","tōngqín","통근"]],[["组成","zǔchéng","이루다"],["脱水","tuōshuǐ","탈수"],["疲劳","píláo","피로"]],[["纪录片","jìlùpiàn","다큐멘터리"],["务工","wùgōng","일하러 나가다"],["打拼","dǎpīn","분투하다"],["安家落户","ānjiā luòhù","정착하다"]]]},{"o":["久坐之后突然进行剧烈运动，容易引发肌肉或韧带拉伤，因此运动前应当充分热身。","一些城市尝试在地铁站周边建设“口袋公园”，为通勤人群提供短暂休憩的空间。","能否有效控制融资成本，是中小企业实现稳定发展的重要保障。","海獭以海胆为食，客观上使海藻林免遭过度啃食，维护了近海生态的平衡。"],"a":2,"type":"양면–한면","why":"앞의 “能否”는 두 면(할 수 있나 없나)인데 뒤의 “重要保障”은 한 면만 맞는다.","fix":"有效控制融资成本，是中小企业实现稳定发展的重要保障。","words":[["休憩","xiūqì","쉬다"],["融资","róngzī","자금 조달"],["海獭","hǎitǎ","해달"],["海胆","hǎidǎn","성게"],["啃食","kěnshí","갉아 먹다"],["韧带","rèndài","인대"],["拉伤","lāshāng","(근육이) 늘어나 다치다"]],"tr":["오래 앉아 있다가 갑자기 격한 운동을 하면 근육이나 인대가 늘어나 다치기 쉬우므로, 운동 전에 준비운동을 충분히 해야 한다.","일부 도시는 지하철역 주변에 ‘포켓 공원’을 만들어 통근하는 사람들이 잠시 쉴 공간을 마련하고 있다.","융자 비용을 효과적으로 관리할 수 있는지는 중소기업이 안정적으로 성장하는 데 중요한 보장이다.","해달은 성게를 먹고 살아서 결과적으로 해초 숲이 지나치게 먹히는 것을 막아 연안 생태계의 균형을 지킨다."],"ow":[[["剧烈","jùliè","격렬하다"],["韧带","rèndài","인대"],["拉伤","lāshāng","(근육이) 늘어나 다치다"],["热身","rèshēn","준비운동하다"]],[["口袋公园","kǒudai gōngyuán","포켓 공원"],["短暂","duǎnzàn","짧다"],["休憩","xiūqì","쉬다"]],[["能否","néngfǒu","~할 수 있는지"],["融资","róngzī","자금 조달"],["保障","bǎozhàng","보장"]],[["海獭","hǎitǎ","해달"],["海胆","hǎidǎn","성게"],["海藻","hǎizǎo","해조"],["啃食","kěnshí","갉아 먹다"]]]},{"o":["视频助理裁判技术的引入，帮助足球裁判纠正了不少关键判罚中的明显错误。","一座城市的房价高低，往往会导致大量年轻人才选择离开，转而到生活成本更低的地方发展。","研究显示，经常与他人进行面对面交流的老年人，认知能力衰退的速度相对较慢。","一些企业利用大数据分析消费者的购买习惯，以便更精准地投放广告。"],"a":1,"type":"양면–한면","why":"앞의 “高低”는 두 면인데 뒤의 “导致……离开”는 집값이 높을 때만 맞는다.","fix":"一座城市的房价过高，往往会导致大量年轻人才选择离开，转而到生活成本更低的地方发展。","words":[["认知","rènzhī","인지"],["衰退","shuāituì","쇠퇴하다"],["精准","jīngzhǔn","정밀하다"],["投放","tóufàng","(광고를) 내보내다"],["裁判","cáipàn","심판"],["判罚","pànfá","판정"]],"tr":["비디오 판독 기술이 들어오면서 축구 심판은 중요한 판정에서 분명한 실수를 꽤 많이 바로잡을 수 있게 되었다.","한 도시의 집값이 비싸면 많은 젊은 인재가 떠나 생활비가 더 낮은 곳으로 옮겨 가는 경우가 많다.","연구에 따르면 다른 사람과 자주 얼굴을 마주하고 이야기하는 노인은 인지 능력이 떨어지는 속도가 비교적 느리다.","일부 기업은 빅데이터로 소비자의 구매 습관을 분석해 광고를 더 정확하게 내보낸다."],"ow":[[["视频助理裁判","shìpín zhùlǐ cáipàn","비디오 판독 심판(VAR)"],["纠正","jiūzhèng","바로잡다"],["判罚","pànfá","판정"]],[["房价","fángjià","집값"],["往往","wǎngwǎng","흔히"],["转而","zhuǎn'ér","방향을 바꾸어"]],[["认知","rènzhī","인지"],["衰退","shuāituì","쇠퇴하다"],["相对","xiāngduì","비교적"]],[["大数据","dàshùjù","빅데이터"],["以便","yǐbiàn","~하기 위하여"],["精准","jīngzhǔn","정밀하다"],["投放","tóufàng","(광고를) 내보내다"]]]},{"o":["随着农村电商的迅速发展，许多山区村庄改变了长期落后的面貌和农民的收入水平。","司南由一把天然磁石琢磨而成的勺子和一个刻有方位的铜盘组成，被认为是指南针的始祖。","心理学研究发现，适度的压力能够调动人的积极性，但长期过大的压力则会损害身心健康。","人口向城市群集中，是工业化和城镇化发展到一定阶段的必然趋势。"],"a":0,"type":"목적어 여럿 중 일부","why":"“改变了”는 “面貌”와는 맞지만 “收入水平”과는 맞지 않는다. 수준은 “提高”한다.","fix":"随着农村电商的迅速发展，许多山区村庄改变了长期落后的面貌，提高了农民的收入水平。","words":[["电商","diànshāng","전자상거래"],["面貌","miànmào","모습"],["司南","sīnán","사남(옛 나침반)"],["磁石","císhí","자석"],["琢磨","zhuómó","갈고 다듬다"],["始祖","shǐzǔ","시조"],["调动","diàodòng","불러일으키다"],["城市群","chéngshìqún","도시군"]],"tr":["농촌 전자상거래가 빠르게 발전하면서 많은 산골 마을이 오랫동안 뒤처졌던 모습과 농민의 소득 수준을 바꾸었다.","사남은 천연 자석을 갈아 만든 숟가락과 방위를 새긴 구리판으로 이루어져 있으며, 나침반의 시조로 여겨진다.","심리학 연구에 따르면 적당한 스트레스는 사람의 의욕을 끌어올리지만, 오래 계속되는 큰 스트레스는 몸과 마음의 건강을 해친다.","인구가 도시군으로 모이는 것은 공업화와 도시화가 일정 단계에 이르면 나타나는 필연적인 흐름이다."],"ow":[[["电商","diànshāng","전자상거래"],["面貌","miànmào","모습"],["落后","luòhòu","뒤떨어지다"]],[["司南","sīnán","사남(옛 나침반)"],["磁石","císhí","자석"],["琢磨","zhuómó","갈고 다듬다"],["方位","fāngwèi","방위"],["始祖","shǐzǔ","시조"]],[["调动","diàodòng","불러일으키다"],["积极性","jījíxìng","의욕"],["损害","sǔnhài","해치다"]],[["城市群","chéngshìqún","도시군"],["工业化","gōngyèhuà","공업화"],["必然","bìrán","필연적이다"]]]}],[{"o":["赵州桥建于隋代，由匠人李春设计，是世界上现存最古老的单孔敞肩石拱桥。","不少大型企业已经将年度社会责任报告的发布视为与公众沟通的重要渠道。","野生东北虎的数量在上世纪一度锐减，经过多年保护，其种群如今正在缓慢恢复。","不仅国内市场表现亮眼，这家家电企业去年在海外市场的销售额比前年同期也增长了三成以上。"],"a":3,"type":"부사 위치","why":"부사 “也”는 개사구 “比前年同期” 앞에 와야 한다. “比……也增长”은 어순이 틀렸다.","fix":"不仅国内市场表现亮眼，这家家电企业去年在海外市场的销售额也比前年同期增长了三成以上。","words":[["赵州桥","Zhàozhōu Qiáo","조주교"],["隋代","Suí dài","수나라 때"],["敞肩","chǎngjiān","아치 어깨가 트인"],["拱桥","gǒngqiáo","아치교"],["渠道","qúdào","경로"],["锐减","ruìjiǎn","급감하다"],["种群","zhǒngqún","개체군"],["亮眼","liàngyǎn","눈에 띄게 좋다"]],"tr":["자오저우교는 수나라 때 지어졌고 장인 이춘이 설계했으며, 현존하는 세계에서 가장 오래된 외아치 개방형 돌다리다.","많은 대기업은 이미 해마다 내는 사회적 책임 보고서를 대중과 소통하는 중요한 통로로 여긴다.","야생 시베리아호랑이는 지난 세기에 한때 크게 줄었으나, 여러 해 보호한 끝에 지금은 개체 수가 천천히 회복되고 있다.","국내 시장의 성적이 좋았을 뿐 아니라, 이 가전 기업의 지난해 해외 매출도 전년 같은 기간보다 30% 넘게 늘었다."],"ow":[[["赵州桥","Zhàozhōu Qiáo","조주교"],["隋代","Suí dài","수나라 때"],["匠人","jiàngrén","장인"],["敞肩","chǎngjiān","아치 어깨가 트인"],["拱桥","gǒngqiáo","아치교"]],[["视为","shìwéi","~로 여기다"],["沟通","gōutōng","소통하다"],["渠道","qúdào","경로"]],[["东北虎","Dōngběihǔ","시베리아호랑이"],["一度","yídù","한때"],["锐减","ruìjiǎn","급감하다"],["种群","zhǒngqún","개체군"]],[["亮眼","liàngyǎn","눈에 띄게 좋다"],["家电","jiādiàn","가전"],["同期","tóngqī","같은 시기"]]]},{"o":["苗族银饰工艺繁复，一套盛装银饰往往需要数位银匠耗费数月才能完成。","城市的夜间灯光数据常被经济学家用来估算一个地区的经济活跃程度。","由于前期市场调研不够充分，这家初创公司把大部分资金没有用在核心产品的研发上，最终错失了发展良机。","植物的叶片之所以呈现绿色，是因为叶绿素吸收了红光和蓝光，而将绿光反射出去。"],"a":2,"type":"부정사 위치","why":"부정사 “没有”는 把 구 앞에 와야 한다. “把……没有用在”은 어순이 틀렸다.","fix":"由于前期市场调研不够充分，这家初创公司没有把大部分资金用在核心产品的研发上，最终错失了发展良机。","words":[["苗族","Miáozú","묘족"],["繁复","fánfù","복잡하다"],["银匠","yínjiàng","은세공인"],["估算","gūsuàn","추산하다"],["初创","chūchuàng","창업 초기의"],["错失","cuòshī","놓치다"],["叶绿素","yèlǜsù","엽록소"],["反射","fǎnshè","반사하다"]],"tr":["먀오족 은장식은 공정이 복잡해서, 한 벌의 성장 은장식을 만드는 데 은세공인 여러 명이 몇 달씩 걸리기도 한다.","경제학자들은 도시의 야간 불빛 자료로 한 지역의 경제 활동이 얼마나 활발한지 추산하곤 한다.","초기 시장 조사가 충분하지 않았던 탓에 이 신생 기업은 자금 대부분을 핵심 제품 개발에 쓰지 못했고, 결국 성장 기회를 놓쳤다.","식물의 잎이 녹색으로 보이는 까닭은 엽록소가 빨간빛과 파란빛을 흡수하고 초록빛을 반사하기 때문이다."],"ow":[[["苗族","Miáozú","묘족"],["繁复","fánfù","복잡하다"],["盛装","shèngzhuāng","성장, 화려한 옷차림"],["银匠","yínjiàng","은세공인"],["耗费","hàofèi","들이다"]],[["估算","gūsuàn","추산하다"],["活跃","huóyuè","활발하다"]],[["调研","diàoyán","조사 연구"],["初创","chūchuàng","창업 초기의"],["研发","yánfā","연구 개발"],["错失","cuòshī","놓치다"]],[["之所以","zhī suǒ yǐ","~한 까닭은"],["呈现","chéngxiàn","나타내다"],["叶绿素","yèlǜsù","엽록소"],["反射","fǎnshè","반사하다"]]]},{"o":["根据第七次全国人口普查数据，全国常住人口超过一千万的城市已有十余个。","这座江南古镇保存完好的明清建筑群，吸引了曾经无数画家和摄影师前来写生、采风。","共享充电宝看似不起眼，却形成了一个规模达上百亿元的市场。","马术是奥运会中唯一由人和动物共同完成的项目，骑手与马匹之间的配合至关重要。"],"a":1,"type":"부사 위치","why":"부사 “曾经”은 동사 “吸引了” 앞에 와야 한다. 목적어 안에 들어가 어순이 틀렸다.","fix":"这座江南古镇保存完好的明清建筑群，曾经吸引了无数画家和摄影师前来写生、采风。","words":[["普查","pǔchá","전면 조사"],["常住人口","chángzhù rénkǒu","상주인구"],["写生","xiěshēng","사생하다"],["采风","cǎifēng","현지 취재하다"],["不起眼","bùqǐyǎn","눈에 띄지 않다"],["马术","mǎshù","승마"],["至关重要","zhì guān zhòng yào","매우 중요하다"]],"tr":["제7차 전국 인구 센서스 자료에 따르면 상주인구가 천만 명이 넘는 도시는 전국에 이미 열몇 곳이다.","잘 보존된 이 강남 옛 마을의 명청 시대 건축물들은 한때 수많은 화가와 사진가를 불러 모아 사생과 현지 취재를 하게 했다.","공유 보조배터리는 눈에 띄지 않아 보이지만 규모가 백억 위안을 넘는 시장을 이루었다.","승마는 올림픽에서 사람과 동물이 함께하는 유일한 종목으로, 기수와 말의 호흡이 무엇보다 중요하다."],"ow":[[["普查","pǔchá","전면 조사"],["常住人口","chángzhù rénkǒu","상주인구"]],[["江南","Jiāngnán","강남(창장 이남)"],["古镇","gǔzhèn","옛 마을"],["写生","xiěshēng","사생하다"],["采风","cǎifēng","현지 취재하다"]],[["充电宝","chōngdiànbǎo","보조배터리"],["不起眼","bù qǐyǎn","눈에 띄지 않다"]],[["马术","mǎshù","승마"],["骑手","qíshǒu","기수"],["马匹","mǎpǐ","말"],["至关重要","zhì guān zhòng yào","매우 중요하다"]]]},{"o":["有关部门关于网约车司机的社会保障问题，目前正在研究制定具体的实施办法。","白居易主张“文章合为时而著，歌诗合为事而作”，他的诗歌语言通俗，在民间流传甚广。","地铁上盖物业的开发模式，既能为轨道交通建设筹集资金，又能带动沿线土地增值。","大象能够通过脚掌感知远处同伴发出的低频震动，从而实现远距离“通话”。"],"a":0,"type":"개사구 위치","why":"“关于” 개사구는 주어 앞에 와야 한다. 주어 “有关部门” 뒤에 놓여 어순이 틀렸다.","fix":"关于网约车司机的社会保障问题，有关部门目前正在研究制定具体的实施办法。","words":[["白居易","Bái Jūyì","백거이"],["通俗","tōngsú","알기 쉽다"],["上盖物业","shànggài wùyè","역 상부 부동산"],["筹集","chóují","모으다"],["增值","zēngzhí","가치가 오르다"],["感知","gǎnzhī","감지하다"],["低频","dīpín","저주파"]],"tr":["관련 부처는 앱 호출 차량 운전기사의 사회 보장 문제에 대해 지금 구체적인 시행 방안을 연구하고 있다.","백거이는 ‘글은 시대를 위해 쓰고 노래와 시는 일을 위해 지어야 한다’고 주장했으며, 그의 시는 말이 쉬워 민간에 널리 퍼졌다.","역 위에 건물을 짓는 개발 방식은 도시철도 건설 자금을 모으는 동시에 노선 주변 땅값도 올린다.","코끼리는 발바닥으로 멀리 있는 동료가 보내는 낮은 진동을 느껴 먼 거리 ‘통화’를 할 수 있다."],"ow":[[["网约车","wǎngyuēchē","앱 호출 차량"],["社会保障","shèhuì bǎozhàng","사회 보장"],["实施","shíshī","실시하다"]],[["白居易","Bái Jūyì","백거이"],["主张","zhǔzhāng","주장하다"],["通俗","tōngsú","알기 쉽다"],["流传","liúchuán","퍼지다"]],[["上盖物业","shànggài wùyè","역 상부 부동산"],["筹集","chóují","모으다"],["沿线","yánxiàn","노선 주변"],["增值","zēngzhí","가치가 오르다"]],[["脚掌","jiǎozhǎng","발바닥"],["感知","gǎnzhī","감지하다"],["低频","dīpín","저주파"],["震动","zhèndòng","진동"]]]},{"o":["昆曲发源于元末明初的江苏昆山，被称为“百戏之祖”，2001年入选首批人类口述和非物质遗产代表作。","随着网购退货率的上升，逆向物流正成为电商企业控制成本时不可忽视的一环。","蒲公英的种子带有白色冠毛，能借助风力飘到很远的地方生根发芽。","这家纺织企业依靠智能化改造扭亏为盈的经验，值得许多传统中小企业学习和借鉴在转型过程中。"],"a":3,"type":"개사구 위치","why":"“在转型过程中”는 동사 “学习和借鉴” 앞에 와야 하는데 문장 끝에 놓였다.","fix":"这家纺织企业依靠智能化改造扭亏为盈的经验，值得许多传统中小企业在转型过程中学习和借鉴。","words":[["昆曲","kūnqǔ","곤곡"],["逆向","nìxiàng","역방향"],["蒲公英","púgōngyīng","민들레"],["冠毛","guānmáo","갓털"],["纺织","fǎngzhī","방직"],["扭亏为盈","niǔ kuī wéi yíng","적자를 흑자로 돌리다"],["借鉴","jièjiàn","본보기로 삼다"]],"tr":["곤곡은 원말 명초 장쑤 쿤산에서 생겨나 ‘백희의 조상’으로 불리며, 2001년 첫 인류 구전 및 무형 유산 걸작에 뽑혔다.","온라인 쇼핑 반품률이 오르면서 역물류는 전자상거래 기업이 비용을 관리할 때 빼놓을 수 없는 부분이 되고 있다.","민들레 씨앗에는 하얀 갓털이 있어 바람을 타고 멀리 날아가 뿌리를 내리고 싹을 틔운다.","이 방직 기업이 스마트 공정 개선으로 적자를 흑자로 돌린 경험은 많은 전통 중소기업이 전환 과정에서 배우고 본받을 만하다."],"ow":[[["昆曲","kūnqǔ","곤곡"],["发源","fāyuán","발원하다"],["昆山","Kūnshān","쿤산(지명)"],["入选","rùxuǎn","뽑히다"]],[["退货率","tuìhuòlǜ","반품률"],["逆向","nìxiàng","역방향"],["物流","wùliú","물류"],["忽视","hūshì","소홀히 하다"]],[["蒲公英","púgōngyīng","민들레"],["冠毛","guānmáo","갓털"],["借助","jièzhù","힘을 빌리다"]],[["纺织","fǎngzhī","방직"],["扭亏为盈","niǔ kuī wéi yíng","적자를 흑자로 돌리다"],["借鉴","jièjiàn","본보기로 삼다"],["转型","zhuǎnxíng","전환하다"]]]},{"o":["新能源汽车产业链的完善，带动了电池、电机、电控等上下游企业的协同发展。","黄河在流经黄土高原时携带了大量泥沙，因而成为世界上含沙量最大的河流之一。","拍卖会上，一张红木的雕花精美的明代书桌以三百万元的价格成交，创下了同类拍品的新纪录。","不少城市在老旧小区改造中加装电梯，为行动不便的老年居民解决了上下楼的难题。"],"a":2,"type":"관형어 순서","why":"재료를 나타내는 “红木”는 중심어 “书桌” 바로 앞에 와야 하고, “雕花精美的”와 “明代”가 그 앞에 와야 한다.","fix":"拍卖会上，一张雕花精美的明代红木书桌以三百万元的价格成交，创下了同类拍品的新纪录。","words":[["产业链","chǎnyèliàn","산업 사슬"],["协同","xiétóng","협력하다"],["黄土高原","Huángtǔ Gāoyuán","황토고원"],["泥沙","níshā","진흙과 모래"],["红木","hóngmù","자단 등 고급 목재"],["雕花","diāohuā","꽃무늬 조각"],["拍品","pāipǐn","경매품"]],"tr":["신에너지차 산업 사슬이 갖춰지면서 배터리, 모터, 전자 제어 등 위아래 단계 기업들이 함께 성장하게 되었다.","황허는 황토고원을 지나며 많은 진흙과 모래를 실어 나르기 때문에 세계에서 모래 함량이 가장 많은 강 가운데 하나가 되었다.","경매에서 조각이 정교한 명나라 자단 책상 하나가 300만 위안에 낙찰되어 같은 종류 경매품의 신기록을 세웠다.","많은 도시가 낡은 아파트 단지를 고치면서 엘리베이터를 달아 거동이 불편한 노인들의 계단 오르내리기 문제를 풀었다."],"ow":[[["产业链","chǎnyèliàn","산업 사슬"],["电控","diànkòng","전자 제어"],["协同","xiétóng","협력하다"]],[["黄土高原","Huángtǔ Gāoyuán","황토고원"],["携带","xiédài","지니다, 싣다"],["泥沙","níshā","진흙과 모래"],["含沙量","hánshāliàng","모래 함량"]],[["拍卖会","pāimàihuì","경매"],["红木","hóngmù","자단 등 고급 목재"],["雕花","diāohuā","꽃무늬 조각"],["成交","chéngjiāo","거래가 성사되다"],["拍品","pāipǐn","경매품"]],[["老旧小区","lǎojiù xiǎoqū","낡은 아파트 단지"],["加装","jiāzhuāng","추가 설치하다"]]]},{"o":["景德镇制瓷历史悠久，素有“瓷都”之称，其制瓷技艺历经千年而不衰。","这是一部反映改革开放以来我国城乡巨大变迁的优秀的由青年导演执导的电视剧。","数据显示，近年来我国居民的服务性消费支出占比逐年提高，旅游、文化和健康消费增长尤为迅速。","骆驼的鼻腔结构特殊，能在呼气时回收水分，这使它能在干旱的沙漠中长时间不喝水。"],"a":1,"type":"관형어 순서","why":"“由青年导演执导的”(누가 만들었나)가 “反映……的” 앞에, 성질을 나타내는 “优秀”는 중심어 바로 앞에 와야 한다.","fix":"这是一部由青年导演执导的、反映改革开放以来我国城乡巨大变迁的优秀电视剧。","words":[["景德镇","Jǐngdézhèn","징더전"],["素有","sùyǒu","예로부터 ~이 있다"],["变迁","biànqiān","변천"],["执导","zhídǎo","감독하다"],["占比","zhànbǐ","차지하는 비중"],["鼻腔","bíqiāng","콧속"],["骆驼","luòtuo","낙타"]],"tr":["징더전은 도자기를 만든 역사가 길어 예로부터 ‘도자기의 수도’라 불렸으며, 그 기술은 천 년이 지나도 쇠퇴하지 않았다.","이 작품은 젊은 감독이 연출한, 개혁개방 이후 우리나라 도시와 농촌의 큰 변화를 담은 우수한 드라마다.","자료에 따르면 최근 우리나라 주민의 서비스 소비 지출 비중이 해마다 높아지고, 여행·문화·건강 소비가 특히 빠르게 늘고 있다.","낙타는 콧속 구조가 특별해 숨을 내쉴 때 수분을 되찾을 수 있어서, 메마른 사막에서 오랫동안 물을 마시지 않고도 버틴다."],"ow":[[["景德镇","Jǐngdézhèn","징더전"],["素有","sùyǒu","예로부터 ~이 있다"],["历经","lìjīng","두루 겪다"]],[["改革开放","gǎigé kāifàng","개혁개방"],["变迁","biànqiān","변천"],["执导","zhídǎo","감독하다"]],[["服务性消费","fúwùxìng xiāofèi","서비스 소비"],["占比","zhànbǐ","차지하는 비중"],["尤为","yóuwéi","특히"]],[["骆驼","luòtuo","낙타"],["鼻腔","bíqiāng","콧속"],["回收","huíshōu","회수하다"],["干旱","gānhàn","가물다"]]]},{"o":["这座城市主干道两旁种着高大的两排法国梧桐，每到秋天，金黄的落叶便成为一道独特的风景。","我国首个国家级新区——上海浦东新区，自1992年设立以来，已成长为全国重要的金融和航运中心。","在关于理性消费的讨论中，“性价比”成为许多年轻人购物时最看重的因素。","针灸通过刺激人体特定穴位来调节气血运行，在减轻慢性疼痛方面效果较为明显。"],"a":0,"type":"관형어 순서","why":"수량어 “两排”가 형용사 “高大的” 앞에 와야 한다.","fix":"这座城市主干道两旁种着两排高大的法国梧桐，每到秋天，金黄的落叶便成为一道独特的风景。","words":[["梧桐","wútóng","플라타너스, 오동"],["浦东","Pǔdōng","푸둥"],["航运","hángyùn","해운"],["性价比","xìngjiàbǐ","가성비"],["针灸","zhēnjiǔ","침구"],["穴位","xuéwèi","혈자리"],["气血","qìxuè","기혈"]],"tr":["이 도시 큰길 양쪽에는 키 큰 플라타너스가 두 줄로 심겨 있어, 가을마다 노란 낙엽이 독특한 풍경이 된다.","우리나라 첫 국가급 신구인 상하이 푸둥 신구는 1992년 세워진 뒤 전국의 중요한 금융·해운 중심으로 성장했다.","합리적 소비에 관한 논의에서 ‘가성비’는 많은 젊은이가 물건을 살 때 가장 중시하는 요소가 되었다.","침구는 몸의 특정 혈자리를 자극해 기혈의 흐름을 조절하며, 만성 통증을 덜어 주는 데 효과가 비교적 뚜렷하다."],"ow":[[["主干道","zhǔgàndào","간선 도로"],["梧桐","wútóng","플라타너스, 오동"],["金黄","jīnhuáng","황금빛"]],[["新区","xīnqū","신구(신개발 지구)"],["浦东","Pǔdōng","푸둥"],["航运","hángyùn","해운"]],[["理性","lǐxìng","이성적"],["性价比","xìngjiàbǐ","가성비"]],[["针灸","zhēnjiǔ","침구"],["刺激","cìjī","자극하다"],["穴位","xuéwèi","혈자리"],["气血","qìxuè","기혈"]]]},{"o":["西汉张骞两次出使西域，开辟了连接东西方的交通要道，史称“凿空”。","一些地方推行“一网通办”，让企业和群众办事从“跑多次”变为“最多跑一次”。","金字塔的建造者并非奴隶，而是领取报酬的工匠和农民，这一观点已得到不少考古证据的支持。","市人大常委会会议审议通过并认真讨论了《城市公共交通条例（草案）》，该条例将于明年起正式施行。"],"a":3,"type":"동작 순서","why":"먼저 “讨论”하고 나서 “审议通过”해야 하는데 순서가 뒤바뀌었다.","fix":"市人大常委会会议认真讨论并审议通过了《城市公共交通条例（草案）》，该条例将于明年起正式施行。","words":[["张骞","Zhāng Qiān","장건"],["西域","Xīyù","서역"],["凿空","záokōng","길을 처음 엶"],["金字塔","jīnzìtǎ","피라미드"],["报酬","bàochou","보수"],["审议","shěnyì","심의하다"],["草案","cǎo'àn","초안"],["施行","shīxíng","시행하다"]],"tr":["서한의 장건은 두 차례 서역에 사신으로 가서 동서를 잇는 교통로를 열었으니, 역사에서는 이를 ‘착공’이라 부른다.","일부 지역은 ‘온라인 원스톱 행정’을 시행해 기업과 시민이 일을 볼 때 ‘여러 번 다니던 것’을 ‘많아야 한 번’으로 줄였다.","피라미드를 지은 사람들은 노예가 아니라 보수를 받는 장인과 농민이었다는 견해는 많은 고고학 증거로 뒷받침되고 있다.","시 인민대표대회 상무위원회 회의는 『도시 대중교통 조례(초안)』을 꼼꼼히 논의하고 심의해 통과시켰으며, 이 조례는 내년부터 정식 시행된다."],"ow":[[["张骞","Zhāng Qiān","장건"],["出使","chūshǐ","사신으로 가다"],["西域","Xīyù","서역"],["开辟","kāipì","개척하다"],["凿空","záokōng","길을 처음 엶"]],[["推行","tuīxíng","널리 시행하다"],["一网通办","yì wǎng tōng bàn","온라인 원스톱 처리"]],[["金字塔","jīnzìtǎ","피라미드"],["并非","bìngfēi","결코 ~이 아니다"],["报酬","bàochou","보수"],["考古","kǎogǔ","고고학"]],[["人大常委会","Réndà Chángwěihuì","인민대표대회 상무위원회"],["审议","shěnyì","심의하다"],["条例","tiáolì","조례"],["草案","cǎo'àn","초안"],["施行","shīxíng","시행하다"]]]},{"o":["沙滩排球于1996年亚特兰大奥运会首次成为正式比赛项目，每队仅由两名队员组成。","在城市化进程中，大量农业人口进入城市，既为工业发展提供了劳动力，也带动了住房、教育等需求的增长。","面对突如其来的市场变化，公司管理层迅速采取对策、分析原因、发现问题，最终稳住了局面。","蚂蚁在觅食时会沿途留下信息素，后来的同伴便循着这种气味找到食物。"],"a":2,"type":"동작 순서","why":"일의 순서는 “发现问题→分析原因→采取对策”인데 거꾸로 나열되었다.","fix":"面对突如其来的市场变化，公司管理层迅速发现问题、分析原因、采取对策，最终稳住了局面。","words":[["突如其来","tū rú qí lái","갑자기 닥치다"],["觅食","mìshí","먹이를 찾다"],["信息素","xìnxīsù","페로몬"],["循","xún","따르다"],["沙滩排球","shātān páiqiú","비치발리볼"],["亚特兰大","Yàtèlándà","애틀랜타"]],"tr":["비치발리볼은 1996년 애틀랜타 올림픽에서 처음 정식 종목이 되었으며, 팀마다 선수가 두 명뿐이다.","도시화 과정에서 많은 농업 인구가 도시로 들어와 공업 발전에 노동력을 주었고, 주거·교육 같은 수요도 늘렸다.","갑자기 닥친 시장 변화 앞에서 회사 경영진은 재빨리 문제를 찾고 원인을 분석해 대책을 세워 마침내 상황을 안정시켰다.","개미는 먹이를 찾을 때 지나는 길에 페로몬을 남기고, 뒤따르는 동료들은 그 냄새를 따라 먹이를 찾아간다."],"ow":[[["沙滩排球","shātān páiqiú","비치발리볼"],["亚特兰大","Yàtèlándà","애틀랜타"],["奥运会","Àoyùnhuì","올림픽"]],[["城市化","chéngshìhuà","도시화"],["进程","jìnchéng","진행 과정"],["劳动力","láodònglì","노동력"]],[["突如其来","tū rú qí lái","갑자기 닥치다"],["对策","duìcè","대책"],["局面","júmiàn","국면"]],[["觅食","mìshí","먹이를 찾다"],["沿途","yántú","길을 따라"],["信息素","xìnxīsù","페로몬"],["循","xún","따르다"]]]}],[{"o":["秦兵马俑形态各异，几乎没有两个面容完全相同的，充分展现了古代工匠的高超技艺。","只有不断提升产品的核心竞争力，中小企业就能在激烈的市场竞争中立于不败之地。","即使在经济增速放缓的情况下，消费者对高品质生活的追求也并未减弱。","铁人三项由游泳、自行车和长跑三个项目连续进行，是对运动员耐力的极限考验。"],"a":1,"type":"짝 오류","why":"“只有”는 “才”와 짝을 이룬다. “只有……就”는 짝이 맞지 않는다.","fix":"只有不断提升产品的核心竞争力，中小企业才能在激烈的市场竞争中立于不败之地。","words":[["兵马俑","bīngmǎyǒng","병마용"],["面容","miànróng","얼굴 생김새"],["增速","zēngsù","성장 속도"],["立于不败之地","lì yú bú bài zhī dì","지지 않을 위치에 서다"],["铁人三项","tiěrén sānxiàng","철인 3종"],["耐力","nàilì","지구력"]],"tr":["진시황 병마용은 모습이 저마다 달라 얼굴이 똑같은 것이 거의 없으며, 고대 장인들의 뛰어난 솜씨를 잘 보여 준다.","중소기업은 제품의 핵심 경쟁력을 끊임없이 높여야만 치열한 시장 경쟁에서 지지 않는 자리에 설 수 있다.","경제 성장이 느려진 상황에서도 좋은 삶을 바라는 소비자의 마음은 약해지지 않았다.","철인 3종은 수영, 자전거, 장거리 달리기를 이어서 하는 경기로, 선수의 지구력을 극한까지 시험한다."],"ow":[[["兵马俑","bīngmǎyǒng","병마용"],["形态各异","xíngtài gè yì","모습이 저마다 다르다"],["面容","miànróng","얼굴 생김새"],["高超","gāochāo","뛰어나다"]],[["核心","héxīn","핵심"],["竞争力","jìngzhēnglì","경쟁력"],["立于不败之地","lì yú bú bài zhī dì","지지 않을 위치에 서다"]],[["增速","zēngsù","성장 속도"],["放缓","fànghuǎn","느려지다"],["减弱","jiǎnruò","약해지다"]],[["铁人三项","tiěrén sānxiàng","철인 3종"],["耐力","nàilì","지구력"],["极限","jíxiàn","극한"]]]},{"o":["无论是在东部沿海的大都市，还是在西部偏远的小山村，移动支付都已渗透到人们生活的方方面面。","跆拳道起源于朝鲜半岛，以腿法为主，2000年悉尼奥运会将其列为正式比赛项目。","宁可多花些时间做好前期论证，也不能让城市规划因草率决策而留下长久的遗憾。","与其把大量资金投入到盲目扩张中，宁可集中力量打造一两款真正有竞争力的产品。"],"a":3,"type":"짝 오류","why":"“与其”는 “不如”와 짝을 이룬다. “与其……宁可”는 짝이 맞지 않는다.","fix":"与其把大量资金投入到盲目扩张中，不如集中力量打造一两款真正有竞争力的产品。","words":[["渗透","shèntòu","스며들다"],["论证","lùnzhèng","타당성 검토"],["草率","cǎoshuài","경솔하다"],["盲目","mángmù","맹목적인"],["扩张","kuòzhāng","확장"],["跆拳道","táiquándào","태권도"],["悉尼","Xīní","시드니"]],"tr":["동부 해안의 대도시든 서부 외딴 산골 마을이든, 모바일 결제는 이미 사람들 생활 곳곳에 스며들었다.","태권도는 한반도에서 시작되어 발기술이 중심이며, 2000년 시드니 올림픽에서 정식 종목이 되었다.","차라리 초기 검토에 시간을 더 들일지언정, 성급한 결정으로 도시 계획에 오래 남을 후회를 만들어서는 안 된다.","많은 돈을 무턱대고 덩치를 키우는 데 쓰기보다는, 힘을 모아 정말 경쟁력 있는 제품 한두 개를 만드는 편이 낫다."],"ow":[[["偏远","piānyuǎn","외지다"],["移动支付","yídòng zhīfù","모바일 결제"],["渗透","shèntòu","스며들다"]],[["跆拳道","táiquándào","태권도"],["朝鲜半岛","Cháoxiǎn Bàndǎo","한반도"],["腿法","tuǐfǎ","발기술"],["悉尼","Xīní","시드니"]],[["宁可","nìngkě","차라리 ~할지언정"],["论证","lùnzhèng","타당성 검토"],["草率","cǎoshuài","경솔하다"]],[["与其","yǔqí","~하기보다는"],["盲目","mángmù","맹목적인"],["扩张","kuòzhāng","확장"],["打造","dǎzào","만들어 내다"]]]},{"o":["既然城市的承载能力有限，才更需要在规划时对人口规模和产业布局进行科学测算。","不管遇到多大的阻力，这位科学家都坚持在戈壁深处开展固沙植物的研究。","虽然这一带的考古发掘工作才刚刚起步，但出土的青铜器已足以证明此地曾是一个重要的都邑。","网络购物节期间，快递员的日均派件量往往是平时的两到三倍。"],"a":0,"type":"짝 오류","why":"“既然”은 “就”와 짝을 이룬다. “既然……才”는 짝이 맞지 않는다.","fix":"既然城市的承载能力有限，就更需要在规划时对人口规模和产业布局进行科学测算。","words":[["承载","chéngzài","수용하다, 감당하다"],["测算","cèsuàn","측정 계산하다"],["戈壁","gēbì","고비, 자갈 사막"],["固沙","gùshā","모래를 고정하다"],["青铜器","qīngtóngqì","청동기"],["都邑","dūyì","도읍"],["派件","pàijiàn","배송하다"]],"tr":["도시가 감당할 수 있는 능력에 한계가 있는 이상, 계획할 때 인구 규모와 산업 배치를 더욱 과학적으로 따져 봐야 한다.","아무리 큰 어려움을 만나도 이 과학자는 고비 사막 깊숙한 곳에서 모래를 붙잡는 식물 연구를 계속했다.","이 일대의 고고학 발굴은 막 시작되었지만, 출토된 청동기만으로도 이곳이 한때 중요한 도읍이었음을 충분히 증명한다.","온라인 쇼핑 축제 기간에는 택배 기사의 하루 평균 배송량이 평소의 두세 배가 되곤 한다."],"ow":[[["既然","jìrán","~한 이상"],["承载","chéngzài","수용하다, 감당하다"],["布局","bùjú","배치"],["测算","cèsuàn","측정 계산하다"]],[["阻力","zǔlì","저항, 방해"],["戈壁","gēbì","고비, 자갈 사막"],["固沙","gùshā","모래를 고정하다"]],[["发掘","fājué","발굴하다"],["出土","chūtǔ","출토되다"],["青铜器","qīngtóngqì","청동기"],["都邑","dūyì","도읍"]],[["快递员","kuàidìyuán","택배 기사"],["日均","rìjūn","하루 평균"],["派件","pàijiàn","배송하다"]]]},{"o":["中国古代的武举制度始创于唐代武则天时期，主要通过骑射、步射和负重等科目选拔武官。","不仅城市居民越来越重视健康饮食，就连许多农村家庭也开始关注食品的营养搭配。","不但这家民营企业在国内市场占据了领先地位，而且还把业务拓展到了东南亚和中东地区。","河豚体内含有剧毒的河豚毒素，如果处理不当，食用后可能危及生命。"],"a":2,"type":"관련사 위치","why":"앞뒤 절의 주어가 같으므로 “不但”은 주어 “这家民营企业” 뒤에 와야 한다.","fix":"这家民营企业不但在国内市场占据了领先地位，而且还把业务拓展到了东南亚和中东地区。","words":[["搭配","dāpèi","배합"],["民营","mínyíng","민영"],["河豚","hétún","복어"],["毒素","dúsù","독소"],["危及","wēijí","위태롭게 하다"],["武举","wǔjǔ","무과"],["武则天","Wǔ Zétiān","측천무후"],["选拔","xuǎnbá","선발하다"]],"tr":["중국 고대의 무과 제도는 당나라 측천무후 때 처음 생겼으며, 주로 말 타고 활쏘기, 걸으며 활쏘기, 무게 들기 등의 과목으로 무관을 뽑았다.","도시 주민만 건강한 식단을 중시하는 것이 아니라, 많은 농촌 가정도 음식의 영양 배합에 관심을 갖기 시작했다.","이 민영 기업은 국내 시장에서 선두 자리를 차지했을 뿐 아니라, 사업을 동남아와 중동까지 넓혔다.","복어 몸에는 독성이 강한 복어 독이 있어, 손질을 잘못하면 먹은 뒤 목숨이 위험할 수 있다."],"ow":[[["武举","wǔjǔ","무과"],["武则天","Wǔ Zétiān","측천무후"],["骑射","qíshè","말 타고 활쏘기"],["选拔","xuǎnbá","선발하다"]],[["饮食","yǐnshí","음식, 식생활"],["营养","yíngyǎng","영양"],["搭配","dāpèi","배합"]],[["民营","mínyíng","민영"],["占据","zhànjù","차지하다"],["拓展","tuòzhǎn","넓히다"]],[["河豚","hétún","복어"],["剧毒","jùdú","맹독"],["毒素","dúsù","독소"],["危及","wēijí","위태롭게 하다"]]]},{"o":["我国是世界上最早种植水稻的国家之一，浙江余姚河姆渡遗址曾出土大量七千年前的稻谷遗存。","如果城市规划者忽视了慢行交通系统的建设，那么不仅居民出行会受到影响，城市的活力而且也会因此下降。","由于远程办公日渐普及，一些写字楼的空置率明显上升，业主不得不下调租金以吸引租户。","海洋吸收了人类排放的大量二氧化碳，这虽然减缓了全球变暖，却也导致海水逐渐酸化。"],"a":1,"type":"관련사 위치","why":"뒤 절의 주어(“城市的活力”)가 앞과 다르므로 “而且”는 주어 앞에 와야 한다.","fix":"如果城市规划者忽视了慢行交通系统的建设，那么不仅居民出行会受到影响，而且城市的活力也会因此下降。","words":[["慢行","mànxíng","보행·자전거 이동"],["余姚","Yúyáo","위야오(지명)"],["河姆渡","Hémǔdù","허무두"],["遗存","yícún","유존물"],["空置率","kōngzhìlǜ","공실률"],["租户","zūhù","임차인"],["酸化","suānhuà","산성화"]],"tr":["우리나라는 세계에서 가장 먼저 벼를 재배한 나라 가운데 하나로, 저장 위야오 허무두 유적에서는 7천 년 전 볍씨 유물이 대량으로 나왔다.","도시 계획가가 보행·자전거 교통 체계를 소홀히 하면 주민의 이동이 불편해질 뿐 아니라 도시의 활력도 떨어진다.","원격 근무가 날로 퍼지면서 일부 오피스 빌딩의 공실률이 크게 올랐고, 건물주들은 세입자를 모으려고 임대료를 내릴 수밖에 없었다.","바다는 인류가 내뿜은 많은 이산화탄소를 흡수해 지구 온난화를 늦췄지만, 그 때문에 바닷물이 점점 산성화되고 있다."],"ow":[[["水稻","shuǐdào","벼"],["余姚","Yúyáo","위야오(지명)"],["河姆渡","Hémǔdù","허무두"],["遗址","yízhǐ","유적"],["遗存","yícún","유존물"]],[["忽视","hūshì","소홀히 하다"],["慢行","mànxíng","보행·자전거 이동"],["活力","huólì","활력"]],[["远程办公","yuǎnchéng bàngōng","원격 근무"],["写字楼","xiězìlóu","오피스 빌딩"],["空置率","kōngzhìlǜ","공실률"],["租户","zūhù","임차인"]],[["排放","páifàng","배출하다"],["二氧化碳","èryǎnghuàtàn","이산화탄소"],["减缓","jiǎnhuǎn","늦추다"],["酸化","suānhuà","산성화"]]]},{"o":["古人之所以把冬至视为“大如年”的节日，是因为这一天过后白昼逐渐变长，阳气开始回升。","尽管智能手机的功能日益强大，但不少老年人仍然对复杂的操作感到无所适从。","研究人员通过分析冰芯中的气泡，还原了过去数十万年间地球大气成分的变化。","由于这款新能源车的续航里程很长、价格也相对亲民，所以上市后的销量一直不太理想。"],"a":3,"type":"논리 관계","why":"주행 거리가 길고 값이 싸다는 것은 판매가 부진한 원인이 될 수 없다. 인과가 아니라 역접(虽然……但是)이어야 한다.","fix":"虽然这款新能源车的续航里程很长、价格也相对亲民，但是上市后的销量一直不太理想。","words":[["冬至","dōngzhì","동지"],["白昼","báizhòu","낮"],["无所适从","wú suǒ shì cóng","어찌할 바를 모르다"],["冰芯","bīngxīn","빙하 코어"],["还原","huányuán","복원하다"],["续航","xùháng","주행 거리, 지속 운행"],["亲民","qīnmín","서민적인, 부담 없는"]],"tr":["옛사람들이 동지를 ‘설만큼 큰’ 명절로 여긴 까닭은 이날이 지나면 낮이 점점 길어지고 양기가 다시 오르기 때문이다.","스마트폰 기능은 날로 강해지지만, 많은 노인은 여전히 복잡한 조작 앞에서 어찌할 바를 모른다.","연구진은 빙하 코어 속 공기 방울을 분석해 지난 수십만 년 동안 지구 대기 성분이 어떻게 변했는지 복원했다.","이 신에너지차는 주행 거리가 길고 값도 비교적 부담 없었지만, 출시 뒤 판매는 줄곧 신통치 않았다."],"ow":[[["之所以","zhī suǒ yǐ","~한 까닭은"],["冬至","dōngzhì","동지"],["白昼","báizhòu","낮"],["阳气","yángqì","양기"]],[["尽管","jǐnguǎn","비록 ~하지만"],["日益","rìyì","날로"],["无所适从","wú suǒ shì cóng","어찌할 바를 모르다"]],[["冰芯","bīngxīn","빙하 코어"],["气泡","qìpào","기포"],["还原","huányuán","복원하다"],["成分","chéngfèn","성분"]],[["续航","xùháng","주행 거리, 지속 운행"],["里程","lǐchéng","거리"],["亲民","qīnmín","부담 없는"]]]},{"o":["这座小城虽然交通便利、产业基础雄厚，但是吸引了大批外地人才前来就业创业。","不只是年轻人热衷于国潮品牌，许多中老年消费者也被富有传统韵味的设计所吸引。","指南针传入欧洲后，为航海家开辟新航路提供了重要的技术条件。","运动生理学研究发现，适量的有氧锻炼能够增强心肌收缩力，降低静息心率。"],"a":0,"type":"논리 관계","why":"교통이 편리하고 산업 기반이 탄탄한 것은 인재를 끄는 이유이므로 역접 “虽然……但是”가 아니라 인과여야 한다.","fix":"这座小城由于交通便利、产业基础雄厚，因而吸引了大批外地人才前来就业创业。","words":[["雄厚","xiónghòu","탄탄하다"],["热衷","rèzhōng","열중하다"],["国潮","guócháo","중국풍 트렌드"],["韵味","yùnwèi","운치"],["航海家","hánghǎijiā","항해가"],["心肌","xīnjī","심근"],["静息","jìngxī","안정 시의"]],"tr":["이 작은 도시는 교통이 편리하고 산업 기반이 탄탄해서 많은 외지 인재를 불러들여 취업과 창업을 하게 했다.","젊은이만 중국풍 브랜드에 빠진 것이 아니라, 많은 중장년 소비자도 전통의 운치가 넘치는 디자인에 끌리고 있다.","나침반이 유럽에 전해진 뒤, 항해가들이 새 항로를 여는 데 중요한 기술적 조건이 되었다.","운동 생리학 연구에 따르면 알맞은 유산소 운동은 심장 근육의 수축력을 키우고 안정 시 심박수를 낮춘다."],"ow":[[["雄厚","xiónghòu","탄탄하다"],["创业","chuàngyè","창업하다"]],[["热衷","rèzhōng","열중하다"],["国潮","guócháo","중국풍 트렌드"],["韵味","yùnwèi","운치"]],[["指南针","zhǐnánzhēn","나침반"],["航海家","hánghǎijiā","항해가"],["开辟","kāipì","개척하다"],["航路","hánglù","항로"]],[["生理学","shēnglǐxué","생리학"],["心肌","xīnjī","심근"],["收缩力","shōusuōlì","수축력"],["静息","jìngxī","안정 시의"]]]},{"o":["每到汛期，洞庭湖便能容纳大量来自长江的洪水，因而被誉为“长江之肾”。","一些城市将闲置的老旧铁路改造成健身步道，让市民在家门口就能散步、骑行和慢跑。","这项新出台的政策不但没有加重小微企业的负担，反而增加了它们的税费支出。","举办大型体育赛事往往能带动当地基础设施建设，但赛后场馆如何持续利用也是一大难题。"],"a":2,"type":"논리 관계","why":"“不但没有……反而”은 뒤에 앞과 반대되는 내용이 와야 하는데, “增加了税费支出”는 부담을 늘린 것이라 앞뒤가 모순된다.","fix":"这项新出台的政策不但没有加重小微企业的负担，反而减少了它们的税费支出。","words":[["汛期","xùnqī","홍수기"],["洞庭湖","Dòngtíng Hú","둥팅호"],["税费","shuìfèi","세금과 수수료"],["步道","bùdào","산책로"],["场馆","chǎngguǎn","경기장"]],"tr":["홍수기가 되면 둥팅호는 창장에서 넘어오는 많은 홍수를 받아들일 수 있어 ‘창장의 콩팥’으로 불린다.","일부 도시는 놀고 있던 낡은 철길을 운동길로 바꾸어, 시민들이 집 앞에서 산책과 자전거, 달리기를 할 수 있게 했다.","새로 나온 이 정책은 소상공인의 부담을 늘리기는커녕 오히려 그들의 세금과 수수료 지출을 줄였다.","큰 체육 대회를 열면 그 지역의 기반 시설 건설이 활발해지지만, 대회가 끝난 뒤 경기장을 어떻게 계속 활용할지도 큰 과제다."],"ow":[[["汛期","xùnqī","홍수기"],["洞庭湖","Dòngtíng Hú","둥팅호"],["容纳","róngnà","수용하다"],["被誉为","bèi yù wéi","~로 칭송받다"]],[["闲置","xiánzhì","놀리다, 방치하다"],["步道","bùdào","산책로"],["骑行","qíxíng","자전거를 타다"]],[["出台","chūtái","(정책을) 내놓다"],["小微企业","xiǎowēi qǐyè","소기업"],["税费","shuìfèi","세금과 수수료"]],[["赛事","sàishì","경기, 대회"],["基础设施","jīchǔ shèshī","기반 시설"],["场馆","chǎngguǎn","경기장"]]]},{"o":["关于人工智能是否会取代人类工作的争论，近年来在社会各界持续升温。","这家咖啡连锁品牌通过下沉市场策略，在三四线城市迅速开设了上千家门店。","位于四川的三星堆遗址出土了大量造型奇特的青铜面具，展现了古蜀文明的独特风貌。","对于如何平衡经济发展与环境保护的问题上，各国专家在本次论坛上展开了激烈的讨论。"],"a":3,"type":"개사 오용","why":"“对于”와 “……上”이 섞였다. “在……问题上”으로 써야 한다.","fix":"在如何平衡经济发展与环境保护的问题上，各国专家在本次论坛上展开了激烈的讨论。","words":[["取代","qǔdài","대체하다"],["升温","shēngwēn","뜨거워지다"],["下沉市场","xiàchén shìchǎng","중소 도시·농촌 시장"],["三星堆","Sānxīngduī","싼싱두이"],["古蜀","Gǔ Shǔ","고촉"],["风貌","fēngmào","풍모"],["论坛","lùntán","포럼"]],"tr":["인공지능이 사람의 일자리를 대신할지를 둘러싼 논쟁은 최근 사회 각계에서 계속 뜨거워지고 있다.","이 커피 체인 브랜드는 중소 도시 시장을 노린 전략으로 3·4선 도시에 빠르게 매장을 천 개 넘게 열었다.","쓰촨의 싼싱두이 유적에서는 모양이 기이한 청동 가면이 많이 나와 고대 촉 문명의 독특한 모습을 보여 준다.","경제 발전과 환경 보호의 균형을 어떻게 잡을지에 대해, 각국 전문가들은 이번 포럼에서 뜨거운 토론을 벌였다."],"ow":[[["人工智能","réngōng zhìnéng","인공지능"],["取代","qǔdài","대체하다"],["争论","zhēnglùn","논쟁"],["升温","shēngwēn","뜨거워지다"]],[["连锁","liánsuǒ","체인"],["下沉市场","xiàchén shìchǎng","중소 도시·농촌 시장"],["策略","cèlüè","전략"]],[["三星堆","Sānxīngduī","싼싱두이"],["遗址","yízhǐ","유적"],["面具","miànjù","가면"],["古蜀","Gǔ Shǔ","고촉"],["风貌","fēngmào","풍모"]],[["平衡","pínghéng","균형을 맞추다"],["论坛","lùntán","포럼"],["激烈","jīliè","치열하다"]]]},{"o":["对于刚进入职场的年轻人来说，合理规划个人财务显得尤为重要。","在政府和社会资本的共同推动，这座城市的地下综合管廊建设取得了突破性进展。","寒武纪生命大爆发是地球生命演化史上的一个重要事件，许多现代动物的祖先在这一时期相继出现。","城市中的大片绿地和水体能够有效减弱“热岛效应”，降低夏季的地表温度。"],"a":1,"type":"개사 오용","why":"“在……推动” 뒤에 “下”가 빠져 개사구가 완성되지 않았다.","fix":"在政府和社会资本的共同推动下，这座城市的地下综合管廊建设取得了突破性进展。","words":[["职场","zhíchǎng","직장"],["管廊","guǎnláng","공동구(지하 관로)"],["突破性","tūpòxìng","획기적인"],["寒武纪","Hánwǔjì","캄브리아기"],["相继","xiāngjì","잇따라"],["热岛效应","rèdǎo xiàoyìng","열섬 효과"],["水体","shuǐtǐ","수역"]],"tr":["사회에 갓 나온 젊은이에게는 개인 재정을 잘 계획하는 일이 특히 중요하다.","정부와 민간 자본이 함께 밀어붙인 결과, 이 도시의 지하 공동구 건설은 획기적인 진전을 이루었다.","캄브리아기 생명 대폭발은 지구 생명 진화사의 중요한 사건으로, 오늘날 많은 동물의 조상이 이 시기에 잇따라 나타났다.","도시의 넓은 녹지와 물가는 ‘열섬 현상’을 효과적으로 약하게 해 여름철 지표 온도를 낮춘다."],"ow":[[["职场","zhíchǎng","직장"],["规划","guīhuà","계획하다"],["财务","cáiwù","재무"],["尤为","yóuwéi","특히"]],[["社会资本","shèhuì zīběn","민간 자본"],["管廊","guǎnláng","공동구(지하 관로)"],["突破性","tūpòxìng","획기적인"]],[["寒武纪","Hánwǔjì","캄브리아기"],["演化","yǎnhuà","진화"],["祖先","zǔxiān","조상"],["相继","xiāngjì","잇따라"]],[["绿地","lǜdì","녹지"],["水体","shuǐtǐ","수역"],["减弱","jiǎnruò","약하게 하다"],["热岛效应","rèdǎo xiàoyìng","열섬 효과"]]]}],[{"o":["我们不能否认，城市化在带来繁荣的同时，也造成了交通拥堵、环境污染等问题。","明代长城的砖石之间用糯米灰浆粘合，因而格外坚固，历经数百年风雨依然屹立。","为了避免消费者不被虚假宣传误导，市场监管部门加大了对直播带货的抽查力度。","鲸类虽然生活在水中，但它们用肺呼吸，必须定期浮出水面换气。"],"a":2,"type":"부정 오류","why":"“避免”과 “不”가 겹쳐 ‘속지 않는 것을 피한다’는 반대 뜻이 되었다.","fix":"为了避免消费者被虚假宣传误导，市场监管部门加大了对直播带货的抽查力度。","words":[["否认","fǒurèn","부인하다"],["糯米","nuòmǐ","찹쌀"],["灰浆","huījiāng","회반죽"],["屹立","yìlì","우뚝 서다"],["虚假","xūjiǎ","허위의"],["带货","dàihuò","(방송으로) 상품을 팔다"],["抽查","chōuchá","표본 검사"],["鲸","jīng","고래"]],"tr":["도시화가 번영을 가져오는 한편 교통 체증과 환경 오염 같은 문제도 낳았다는 것을 우리는 부인할 수 없다.","명나라 장성의 벽돌과 돌 사이는 찹쌀 회반죽으로 붙여 매우 단단해서, 수백 년의 비바람을 겪고도 여전히 우뚝 서 있다.","소비자가 허위 광고에 속지 않도록, 시장 감독 당국은 라이브 커머스에 대한 표본 검사를 강화했다.","고래류는 물속에 살지만 폐로 숨을 쉬기 때문에 주기적으로 물 위로 올라와 숨을 바꿔야 한다."],"ow":[[["否认","fǒurèn","부인하다"],["繁荣","fánróng","번영"],["拥堵","yōngdǔ","막히다"]],[["糯米","nuòmǐ","찹쌀"],["灰浆","huījiāng","회반죽"],["粘合","zhānhé","붙이다"],["屹立","yìlì","우뚝 서다"]],[["虚假","xūjiǎ","허위의"],["误导","wùdǎo","잘못 이끌다"],["带货","dàihuò","(방송으로) 상품을 팔다"],["抽查","chōuchá","표본 검사"]],[["鲸类","jīnglèi","고래류"],["肺","fèi","폐"],["定期","dìngqī","정기적으로"]]]},{"o":["谁也无法否认，充分而稳定的就业不是保障和改善民生最重要的基础。","这家百年药企之所以能历久弥新，在于它始终坚持“炮制虽繁必不敢省人工”的祖训。","在热带雨林中，许多植物的叶片末端长有“滴水叶尖”，以便迅速排走积水。","共享经济的发展，难免会对传统行业的既有利益格局造成一定冲击。"],"a":0,"type":"부정 오류","why":"“无法否认”과 “不是”가 겹쳐 ‘취업이 기초가 아니다’라는 반대 뜻이 되었다.","fix":"谁也无法否认，充分而稳定的就业是保障和改善民生最重要的基础。","words":[["民生","mínshēng","민생"],["历久弥新","lì jiǔ mí xīn","오래될수록 새로워지다"],["炮制","páozhì","(한약재를) 법제하다"],["祖训","zǔxùn","선대의 가르침"],["雨林","yǔlín","우림"],["既有","jìyǒu","기존의"],["格局","géjú","구도"]],"tr":["충분하고 안정된 일자리가 민생을 지키고 나아지게 하는 가장 중요한 기초라는 점은 누구도 부인할 수 없다.","이 백 년 된 제약 회사가 오래될수록 새로워질 수 있었던 것은 ‘만드는 과정이 번거로워도 품을 아끼지 않는다’는 선대의 가르침을 늘 지켰기 때문이다.","열대 우림에서는 많은 식물의 잎 끝에 ‘물방울 잎끝’이 있어 고인 물을 빨리 흘려보낸다.","공유 경제가 발전하면 기존 산업의 이익 구도에 어느 정도 충격을 주는 것은 피하기 어렵다."],"ow":[[["否认","fǒurèn","부인하다"],["民生","mínshēng","민생"]],[["药企","yàoqǐ","제약 회사"],["历久弥新","lì jiǔ mí xīn","오래될수록 새로워지다"],["炮制","páozhì","(한약재를) 법제하다"],["祖训","zǔxùn","선대의 가르침"]],[["热带雨林","rèdài yǔlín","열대 우림"],["叶片","yèpiàn","잎"],["以便","yǐbiàn","~하기 위하여"]],[["难免","nánmiǎn","피하기 어렵다"],["既有","jìyǒu","기존의"],["格局","géjú","구도"],["冲击","chōngjī","충격"]]]},{"o":["专家提醒，长时间低头看手机极易对颈椎造成损伤，即便是年轻人也不可掉以轻心。","白鹤梁题刻位于重庆涪陵的长江江心，记录了一千二百多年间长江枯水期的水位变化，被誉为“世界第一古代水文站”。","并不是所有的城市都适合发展大规模的制造业，因地制宜才是区域发展的明智选择。","新修订的条例明确规定，严禁餐饮企业在外卖包装中不使用一次性不可降解的塑料餐具。"],"a":3,"type":"부정 오류","why":"“严禁”과 “不使用”이 겹쳐 ‘쓰지 않는 것을 금지한다’는 반대 뜻이 되었다.","fix":"新修订的条例明确规定，严禁餐饮企业在外卖包装中使用一次性不可降解的塑料餐具。","words":[["颈椎","jǐngzhuī","경추"],["掉以轻心","diào yǐ qīng xīn","방심하다"],["白鹤梁","Báihè Liáng","바이허량"],["涪陵","Fúlíng","푸링"],["水文","shuǐwén","수문"],["因地制宜","yīn dì zhì yí","실정에 맞게 하다"],["修订","xiūdìng","개정하다"],["降解","jiàngjiě","분해되다"]],"tr":["전문가들은 오래 고개를 숙이고 휴대폰을 보면 목뼈를 다치기 아주 쉬우므로 젊은 사람도 방심해서는 안 된다고 경고한다.","충칭 푸링의 창장 한가운데 있는 백학량 석각은 1200여 년 동안 창장 갈수기의 수위 변화를 기록해 ‘세계 제일의 고대 수문 관측소’로 불린다.","모든 도시가 대규모 제조업에 맞는 것은 아니며, 실정에 맞게 하는 것이야말로 지역 발전의 현명한 선택이다.","새로 개정된 조례는 음식점이 배달 포장에 일회용 비분해성 플라스틱 식기를 쓰지 못하도록 엄격히 금지한다고 분명히 정했다."],"ow":[[["颈椎","jǐngzhuī","경추"],["损伤","sǔnshāng","손상"],["即便","jíbiàn","설령 ~하더라도"],["掉以轻心","diào yǐ qīng xīn","방심하다"]],[["白鹤梁","Báihè Liáng","바이허량"],["题刻","tíkè","석각 글"],["涪陵","Fúlíng","푸링"],["枯水期","kūshuǐqī","갈수기"],["水文站","shuǐwénzhàn","수문 관측소"]],[["并不是","bìng bú shì","결코 ~이 아니다"],["制造业","zhìzàoyè","제조업"],["因地制宜","yīn dì zhì yí","실정에 맞게 하다"]],[["修订","xiūdìng","개정하다"],["条例","tiáolì","조례"],["严禁","yánjìn","엄금하다"],["降解","jiàngjiě","분해되다"]]]},{"o":["隋唐大运河以洛阳为中心，北抵涿郡，南达余杭，全长两千七百多公里。","由于采用了新型节能材料，这栋办公楼的年耗电量比改造前降低了一倍。","该口岸的跨境电商出口额比五年前增加了两倍，成为带动当地外贸增长的新引擎。","定向越野要求参赛者借助地图和指北针，在最短时间内依次到达各个检查点。"],"a":1,"type":"배수 감소","why":"줄어드는 것에는 “倍”를 쓰지 않는다. “降低了一倍”가 아니라 “降低了一半”이라고 해야 한다.","fix":"由于采用了新型节能材料，这栋办公楼的年耗电量比改造前降低了一半。","words":[["涿郡","Zhuō Jùn","탁군"],["余杭","Yúháng","여항"],["节能","jiénéng","에너지 절약"],["耗电量","hàodiànliàng","전력 소비량"],["口岸","kǒu'àn","통상구"],["引擎","yǐnqíng","엔진, 원동력"],["定向越野","dìngxiàng yuèyě","오리엔티어링"],["依次","yīcì","차례로"]],"tr":["수당 대운하는 뤄양을 중심으로 북쪽으로 탁군, 남쪽으로 여항까지 이어지며 전체 길이가 2700여 킬로미터다.","새 에너지 절약 자재를 쓴 덕분에 이 사무용 건물의 한 해 전력 사용량이 개조 전보다 크게 줄었다.","이 통상구의 국경 간 전자상거래 수출액은 5년 전보다 세 배가 되어 지역 대외 무역 성장을 이끄는 새 엔진이 되었다.","오리엔티어링은 참가자가 지도와 나침반을 써서 가장 짧은 시간에 여러 확인 지점을 차례로 찾아가는 경기다."],"ow":[[["大运河","Dà Yùnhé","대운하"],["洛阳","Luòyáng","뤄양"],["涿郡","Zhuō Jùn","탁군"],["余杭","Yúháng","여항"]],[["节能","jiénéng","에너지 절약"],["耗电量","hàodiànliàng","전력 소비량"],["改造","gǎizào","개조하다"]],[["口岸","kǒu'àn","통상구"],["跨境电商","kuàjìng diànshāng","국경 간 전자상거래"],["外贸","wàimào","대외 무역"],["引擎","yǐnqíng","엔진, 원동력"]],[["定向越野","dìngxiàng yuèyě","오리엔티어링"],["借助","jièzhù","힘을 빌리다"],["指北针","zhǐběizhēn","나침반"],["依次","yīcì","차례로"]]]},{"o":["相扑是日本的传统体育项目，力士通过把对手推出圆形赛台或使其脚掌以外的部位着地来取胜。","随着人均寿命的延长，“银发经济”逐渐成为拉动消费的新增长点。","引入机器视觉检测系统后，这家汽车零部件工厂的产品不良率降低了三倍，生产效率也明显提升。","气象学上通常以连续五天日平均气温稳定在十摄氏度以上作为入春的标准。"],"a":2,"type":"배수 감소","why":"감소에는 “倍”를 쓸 수 없다. “降低了三倍”는 틀리고 분수로 나타내야 한다.","fix":"引入机器视觉检测系统后，这家汽车零部件工厂的产品不良率降低到了原来的四分之一，生产效率也明显提升。","words":[["银发经济","yínfà jīngjì","실버 경제"],["视觉","shìjué","시각"],["零部件","língbùjiàn","부품"],["不良率","bùliánglǜ","불량률"],["气象学","qìxiàngxué","기상학"],["相扑","xiāngpū","스모"],["着地","zháodì","땅에 닿다"]],"tr":["스모는 일본의 전통 체육 종목으로, 선수는 상대를 둥근 씨름판 밖으로 밀어내거나 발바닥이 아닌 몸의 부위를 땅에 닿게 하면 이긴다.","평균 수명이 늘어나면서 ‘실버 경제’가 소비를 끌어올리는 새로운 성장 동력이 되고 있다.","머신 비전 검사 시스템을 들인 뒤 이 자동차 부품 공장의 불량률은 크게 떨어졌고 생산 효율도 눈에 띄게 높아졌다.","기상학에서는 보통 하루 평균 기온이 5일 연속 10도 이상을 유지하는 것을 봄이 시작되는 기준으로 삼는다."],"ow":[[["相扑","xiāngpū","스모"],["力士","lìshì","역사(스모 선수)"],["脚掌","jiǎozhǎng","발바닥"],["着地","zháodì","땅에 닿다"]],[["寿命","shòumìng","수명"],["银发经济","yínfà jīngjì","실버 경제"],["拉动","lādòng","끌어올리다"]],[["视觉","shìjué","시각"],["零部件","língbùjiàn","부품"],["不良率","bùliánglǜ","불량률"]],[["气象学","qìxiàngxué","기상학"],["摄氏度","shèshìdù","섭씨 온도"],["入春","rùchūn","봄으로 접어들다"]]]},{"o":["这次招聘会吸引了应届毕业生、外地务工人员和年轻人等各类求职者三万余人次参与。","运动员在比赛前适当补充碳水化合物，可以增加肌糖原储备，延缓疲劳的出现。","近年来，越来越多的企业选择将数据中心建在贵州，看中的是当地凉爽的气候和充足的电力。","蚯蚓在土壤中钻洞穿行，能使土壤变得疏松，有利于植物根系的生长。"],"a":0,"type":"범위·분류","why":"“年轻人”은 “应届毕业生”, “外地务工人员”과 범위가 겹쳐 함께 나열할 수 없다.","fix":"这次招聘会吸引了应届毕业生、外地务工人员和退役军人等各类求职者三万余人次参与。","words":[["应届","yīngjiè","그해 졸업하는"],["蚯蚓","qiūyǐn","지렁이"],["疏松","shūsōng","푸석하다"],["碳水化合物","tànshuǐ huàhéwù","탄수화물"],["肌糖原","jītángyuán","근글리코겐"],["延缓","yánhuǎn","늦추다"]],"tr":["이번 채용 박람회에는 올해 졸업생, 외지 출신 노동자, 젊은이 등 각종 구직자가 연인원 3만여 명 참가했다.","선수가 경기 전에 탄수화물을 알맞게 보충하면 근글리코겐 저장량이 늘어 피로가 늦게 찾아온다.","최근 점점 더 많은 기업이 데이터 센터를 구이저우에 짓는데, 그곳의 선선한 기후와 넉넉한 전력을 보기 때문이다.","지렁이는 흙 속에 굴을 뚫고 다니며 흙을 푸석하게 만들어 식물 뿌리가 자라는 데 도움을 준다."],"ow":[[["招聘会","zhāopìnhuì","채용 박람회"],["应届","yīngjiè","그해 졸업하는"],["务工","wùgōng","일하러 나가다"],["人次","réncì","연인원"]],[["碳水化合物","tànshuǐ huàhéwù","탄수화물"],["肌糖原","jītángyuán","근글리코겐"],["储备","chǔbèi","저장"],["延缓","yánhuǎn","늦추다"]],[["数据中心","shùjù zhōngxīn","데이터 센터"],["贵州","Guìzhōu","구이저우"],["凉爽","liángshuǎng","선선하다"]],[["蚯蚓","qiūyǐn","지렁이"],["疏松","shūsōng","푸석하다"],["根系","gēnxì","뿌리"]]]},{"o":["一些新一线城市凭借较低的生活成本和优惠的人才政策，正在吸引越来越多的年轻人前来定居。","人体无法自行合成某些必需氨基酸，必须通过食物摄取。","地铁客流量的潮汐式变化，直观地反映出城市职住分离的现状。","博物馆新开设的展厅陈列着商周青铜器、汉代玉器、唐代三彩和古代文物等数百件珍品。"],"a":3,"type":"범위·분류","why":"“古代文物”은 앞의 청동기·옥기·삼채를 모두 포함하는 큰 범주라 함께 나열할 수 없다.","fix":"博物馆新开设的展厅陈列着商周青铜器、汉代玉器、唐代三彩和宋代瓷器等数百件珍品。","words":[["定居","dìngjū","정착하다"],["氨基酸","ānjīsuān","아미노산"],["摄取","shèqǔ","섭취하다"],["潮汐","cháoxī","밀물과 썰물"],["职住分离","zhí zhù fēnlí","직장과 주거의 분리"],["陈列","chénliè","진열하다"],["玉器","yùqì","옥기"],["三彩","sāncǎi","삼채"]],"tr":["일부 신1선 도시는 비교적 낮은 생활비와 혜택이 많은 인재 정책으로 점점 더 많은 젊은이를 정착하게 하고 있다.","사람 몸은 일부 필수 아미노산을 스스로 만들 수 없어서 반드시 음식으로 섭취해야 한다.","지하철 이용객이 밀물·썰물처럼 오가는 변화는 도시에서 직장과 집이 떨어져 있는 현실을 한눈에 보여 준다.","박물관에 새로 연 전시실에는 상주 시대 청동기, 한나라 옥기, 당삼채, 고대 문물 등 수백 점의 귀한 유물이 전시되어 있다."],"ow":[[["新一线城市","xīn yīxiàn chéngshì","신1선 도시"],["凭借","píngjiè","~에 힘입어"],["优惠","yōuhuì","혜택의"],["定居","dìngjū","정착하다"]],[["合成","héchéng","합성하다"],["氨基酸","ānjīsuān","아미노산"],["摄取","shèqǔ","섭취하다"]],[["客流量","kèliúliàng","승객 수"],["潮汐","cháoxī","밀물과 썰물"],["职住分离","zhí zhù fēnlí","직장과 주거의 분리"]],[["陈列","chénliè","진열하다"],["青铜器","qīngtóngqì","청동기"],["玉器","yùqì","옥기"],["三彩","sāncǎi","삼채"],["珍品","zhēnpǐn","진품"]]]},{"o":["被称为“东方建筑明珠”的应县木塔，建于辽代，是世界上现存最高大的木结构塔式建筑。","专家分析认为，今年国内旅游市场的总收入肯定大概会超过疫情前的水平。","部分城市推行“弹性退休”试点，允许符合条件的职工自愿选择推迟退休。","萤火虫发光是体内荧光素在酶的作用下发生氧化的结果。"],"a":1,"type":"자기모순","why":"“肯定”(확실히)과 “大概”(아마)가 함께 쓰여 앞뒤가 모순된다.","fix":"专家分析认为，今年国内旅游市场的总收入肯定会超过疫情前的水平。","words":[["应县木塔","Yìngxiàn Mùtǎ","응현 목탑"],["辽代","Liáo dài","요나라 때"],["试点","shìdiǎn","시범 실시"],["萤火虫","yínghuǒchóng","반딧불이"],["荧光素","yíngguāngsù","루시페린"],["酶","méi","효소"],["氧化","yǎnghuà","산화"]],"tr":["‘동방 건축의 진주’로 불리는 응현 목탑은 요나라 때 지어졌으며, 현존하는 세계에서 가장 높고 큰 목조 탑 건축물이다.","전문가들은 올해 국내 관광 시장의 총수입이 틀림없이 코로나 이전 수준을 넘을 것이라고 분석했다.","일부 도시는 ‘탄력 정년’을 시범 운영해, 조건에 맞는 직원이 스스로 원하면 퇴직을 늦출 수 있게 했다.","반딧불이가 빛을 내는 것은 몸속 루시페린이 효소의 작용으로 산화되기 때문이다."],"ow":[[["应县木塔","Yìngxiàn Mùtǎ","응현 목탑"],["辽代","Liáo dài","요나라 때"],["现存","xiàncún","현존하다"]],[["总收入","zǒngshōurù","총수입"],["疫情","yìqíng","전염병 상황"]],[["弹性","tánxìng","탄력적인"],["试点","shìdiǎn","시범 실시"],["自愿","zìyuàn","자원하다"]],[["萤火虫","yínghuǒchóng","반딧불이"],["荧光素","yíngguāngsù","루시페린"],["酶","méi","효소"],["氧化","yǎnghuà","산화"]]]},{"o":["该市去年新增的五万个就业岗位中，服务业约占六成，制造业约占五成，其余来自农业和建筑业。","安徽宏村被称为“画里乡村”，其村落布局形似一头卧牛，水系设计巧夺天工。","消费者权益保护法规定，经营者不得以格式条款排除或者限制消费者的权利。","地衣是真菌与藻类共生形成的复合体，常被称为植物界的“开路先锋”。"],"a":0,"type":"자기모순","why":"서비스업 6할과 제조업 5할을 더하면 이미 100%를 넘으므로 “其余”가 있을 수 없어 숫자가 모순된다.","fix":"该市去年新增的五万个就业岗位中，服务业约占六成，制造业约占三成，其余来自农业和建筑业。","words":[["宏村","Hóngcūn","훙춘"],["巧夺天工","qiǎo duó tiān gōng","솜씨가 자연을 능가하다"],["权益","quányì","권익"],["格式条款","géshì tiáokuǎn","약관"],["地衣","dìyī","지의류"],["藻类","zǎolèi","조류"],["共生","gòngshēng","공생하다"]],"tr":["이 시에서 지난해 새로 생긴 일자리 5만 개 가운데 서비스업이 약 6할, 제조업이 약 5할이고, 나머지는 농업과 건설업에서 나왔다.","안후이 훙춘은 ‘그림 속 마을’로 불리며, 마을 배치가 누운 소 모양이고 물길 설계는 자연을 넘어설 만큼 정교하다.","소비자권익보호법은 사업자가 약관으로 소비자의 권리를 없애거나 제한해서는 안 된다고 정하고 있다.","지의류는 진균과 조류가 공생해 이룬 복합체로, 흔히 식물계의 ‘개척 선봉’이라 불린다."],"ow":[[["岗位","gǎngwèi","일자리"],["制造业","zhìzàoyè","제조업"],["其余","qíyú","나머지"]],[["宏村","Hóngcūn","훙춘"],["布局","bùjú","배치"],["卧牛","wòniú","누운 소"],["巧夺天工","qiǎo duó tiān gōng","솜씨가 자연을 능가하다"]],[["权益","quányì","권익"],["经营者","jīngyíngzhě","사업자"],["格式条款","géshì tiáokuǎn","약관"]],[["地衣","dìyī","지의류"],["真菌","zhēnjūn","진균"],["藻类","zǎolèi","조류"],["共生","gòngshēng","공생하다"],["先锋","xiānfēng","선봉"]]]},{"o":["苏绣以针法精细、色彩雅致著称，与湘绣、蜀绣、粤绣并称中国“四大名绣”。","物价指数是衡量通货膨胀程度的重要指标，它的变动直接关系到居民的实际购买力。","作为该省唯一的国家级经济技术开发区之一，这里聚集了上百家高新技术企业。","坐落于四川乐山的乐山大佛开凿于唐代，前后历时约九十年才最终完工。"],"a":2,"type":"자기모순","why":"“唯一的”(유일한)과 “之一”(여럿 중 하나)이 함께 쓰여 모순된다.","fix":"作为该省唯一的国家级经济技术开发区，这里聚集了上百家高新技术企业。","words":[["苏绣","sūxiù","쑤저우 자수"],["针法","zhēnfǎ","바느질 기법"],["雅致","yǎzhì","우아하다"],["通货膨胀","tōnghuò péngzhàng","인플레이션"],["购买力","gòumǎilì","구매력"],["高新技术","gāoxīn jìshù","첨단 기술"],["乐山","Lèshān","러산"]],"tr":["쑤저우 자수는 바느질이 섬세하고 색이 우아하기로 이름나, 후난·쓰촨·광둥 자수와 함께 중국 ‘4대 자수’로 꼽힌다.","물가 지수는 인플레이션 정도를 재는 중요한 지표로, 그 변동은 주민의 실제 구매력과 바로 이어진다.","이곳은 이 성의 유일한 국가급 경제기술개발구로서 백여 개의 첨단 기술 기업이 모여 있다.","쓰촨 러산에 자리한 러산 대불은 당나라 때 깎아 만들기 시작해 약 90년이 걸려서야 완성되었다."],"ow":[[["苏绣","sūxiù","쑤저우 자수"],["针法","zhēnfǎ","바느질 기법"],["雅致","yǎzhì","우아하다"],["湘绣","xiāngxiù","후난 자수"]],[["物价指数","wùjià zhǐshù","물가 지수"],["衡量","héngliáng","가늠하다"],["通货膨胀","tōnghuò péngzhàng","인플레이션"],["购买力","gòumǎilì","구매력"]],[["开发区","kāifāqū","개발구"],["聚集","jùjí","모이다"],["高新技术","gāoxīn jìshù","첨단 기술"]],[["坐落","zuòluò","자리 잡다"],["乐山大佛","Lèshān Dàfó","러산 대불"],["开凿","kāizáo","파서 만들다"],["完工","wángōng","완공하다"]]]}],[{"o":["近年来部分城市出现“空城”现象，主要原因是盲目开发新区、产业支撑不足造成的。","唐代鉴真和尚六次东渡，终于抵达日本，为中日文化交流作出了卓越贡献。","一些餐饮企业推出“小份菜”和“半份菜”，既满足了顾客多样化的需求，又减少了食物浪费。","研究发现，在儿童成长过程中，父母的陪伴比物质条件对其性格塑造的影响更为深远。"],"a":0,"type":"구식 혼합","why":"“原因是……”와 “是……造成的” 두 문형이 섞였다. 둘 중 하나만 써야 한다.","fix":"近年来部分城市出现“空城”现象，主要是盲目开发新区、产业支撑不足造成的。","words":[["盲目","mángmù","무턱대고"],["支撑","zhīchēng","받침, 뒷받침"],["鉴真","Jiànzhēn","감진"],["东渡","dōngdù","동쪽으로 바다를 건너다"],["卓越","zhuóyuè","탁월하다"],["陪伴","péibàn","곁에 있어 주다"],["塑造","sùzào","빚어 만들다"]],"tr":["최근 일부 도시에 ‘텅 빈 도시’ 현상이 나타났는데, 주된 원인은 무턱대고 신구를 개발하고 산업의 뒷받침이 부족했기 때문이다.","당나라 감진 스님은 여섯 번째 시도 끝에 일본에 닿아 중일 문화 교류에 탁월한 공헌을 했다.","일부 음식점은 ‘작은 접시’와 ‘반 접시’ 메뉴를 내놓아 손님의 다양한 요구를 채우는 동시에 음식 낭비도 줄였다.","연구에 따르면 아이가 자라는 동안 부모가 곁에 있어 주는 것이 물질적 조건보다 성격 형성에 더 깊은 영향을 준다."],"ow":[[["盲目","mángmù","무턱대고"],["新区","xīnqū","신구(신개발 지구)"],["支撑","zhīchēng","받침, 뒷받침"]],[["鉴真","Jiànzhēn","감진"],["和尚","héshang","스님"],["东渡","dōngdù","동쪽으로 바다를 건너다"],["卓越","zhuóyuè","탁월하다"]],[["餐饮","cānyǐn","요식업"],["多样化","duōyànghuà","다양화"]],[["陪伴","péibàn","곁에 있어 주다"],["物质","wùzhì","물질"],["塑造","sùzào","빚어 만들다"],["深远","shēnyuǎn","깊고 크다"]]]},{"o":["汉字的造字方法主要有象形、指事、会意和形声四种，其中形声字的数量最多。","城市的公共图书馆不仅是借阅书籍的场所，也越来越成为市民交流和学习的“第三空间”。","牡丹被誉为“花中之王”，洛阳因种植牡丹历史悠久而享有“牡丹花城”的美誉。","这座海滨城市过去的经济发展主要靠渔业和港口贸易为主，如今旅游业已成为支柱产业。"],"a":3,"type":"구식 혼합","why":"“靠……”와 “以……为主” 두 문형이 섞여 “靠……为主”가 되었다.","fix":"这座海滨城市过去的经济发展主要靠渔业和港口贸易，如今旅游业已成为支柱产业。","words":[["象形","xiàngxíng","상형"],["会意","huìyì","회의"],["形声","xíngshēng","형성"],["借阅","jièyuè","빌려 읽다"],["牡丹","mǔdan","모란"],["美誉","měiyù","명성"],["海滨","hǎibīn","해변"],["支柱","zhīzhù","기둥"]],"tr":["한자를 만드는 방법은 주로 상형, 지사, 회의, 형성 네 가지이며, 그중 형성자가 가장 많다.","도시의 공공 도서관은 책을 빌려 읽는 곳일 뿐 아니라, 점점 시민들이 교류하고 배우는 ‘제3의 공간’이 되고 있다.","모란은 ‘꽃 중의 왕’으로 불리며, 뤄양은 모란을 기른 역사가 길어 ‘모란의 도시’라는 명성을 누린다.","이 해변 도시는 예전에 주로 어업과 항구 무역에 기대어 경제를 키웠지만, 지금은 관광업이 기둥 산업이 되었다."],"ow":[[["象形","xiàngxíng","상형"],["指事","zhǐshì","지사"],["会意","huìyì","회의"],["形声","xíngshēng","형성"]],[["借阅","jièyuè","빌려 읽다"],["场所","chǎngsuǒ","장소"]],[["牡丹","mǔdan","모란"],["洛阳","Luòyáng","뤄양"],["享有","xiǎngyǒu","누리다"],["美誉","měiyù","명성"]],[["海滨","hǎibīn","해변"],["渔业","yúyè","어업"],["支柱产业","zhīzhù chǎnyè","기간산업"]]]},{"o":["汉代的马踏飞燕铜像构思精巧，造型生动，被确定为中国旅游业的标志。","一个地区能否留住外来人口，关键在于能否提供稳定的就业机会和公平的公共服务起着决定性作用。","蜘蛛丝的强度极高，同样粗细的蛛丝比钢丝还要坚韧数倍。","越来越多的城市年轻人选择租房而非购房，这在一定程度上改变了住房市场的供需结构。"],"a":1,"type":"구식 혼합","why":"“关键在于……”와 “……起着决定性作用” 두 문형이 섞였다.","fix":"一个地区能否留住外来人口，关键在于能否提供稳定的就业机会和公平的公共服务。","words":[["马踏飞燕","Mǎ Tà Fēi Yàn","마답비연(청동 분마상)"],["构思","gòusī","구상"],["精巧","jīngqiǎo","정교하다"],["蜘蛛","zhīzhū","거미"],["坚韧","jiānrèn","강인하다"],["供需","gōngxū","수요와 공급"]],"tr":["한나라의 ‘마답비연’ 청동상은 구상이 정교하고 모습이 생생해 중국 관광의 상징으로 정해졌다.","한 지역이 외지 인구를 붙잡을 수 있는지는 안정된 일자리와 공평한 공공 서비스를 줄 수 있는지에 달려 있다.","거미줄은 강도가 매우 높아 같은 굵기라면 강철선보다 몇 배나 더 질기다.","점점 더 많은 도시 청년이 집을 사는 대신 빌려 살기를 택하면서, 주택 시장의 수요와 공급 구조가 어느 정도 바뀌었다."],"ow":[[["马踏飞燕","Mǎ Tà Fēi Yàn","마답비연(청동 분마상)"],["构思","gòusī","구상"],["精巧","jīngqiǎo","정교하다"]],[["能否","néngfǒu","~할 수 있는지"],["关键在于","guānjiàn zàiyú","관건은 ~에 있다"],["公平","gōngpíng","공평하다"]],[["蜘蛛丝","zhīzhūsī","거미줄"],["强度","qiángdù","강도"],["坚韧","jiānrèn","강인하다"]],[["而非","ér fēi","~이 아니라"],["供需","gōngxū","수요와 공급"]]]},{"o":["古琴是中国历史最悠久的弹拨乐器之一，其音色深沉悠远，常被文人用来寄托情怀。","一些企业实行“四天工作制”试点，结果显示员工的工作效率并没有因此降低。","该地区近年来人口持续外流，是产业结构单一、公共服务滞后所致的结果。","跳绳看似简单，却能同时锻炼心肺功能、身体协调能力和下肢力量。"],"a":2,"type":"구식 혼합","why":"“是……的结果”와 “是……所致” 두 문형이 섞여 “所致的结果”가 되었다.","fix":"该地区近年来人口持续外流，是产业结构单一、公共服务滞后所致。","words":[["古琴","gǔqín","고금(칠현금)"],["弹拨","tánbō","현을 튕기는"],["寄托","jìtuō","의탁하다"],["外流","wàiliú","유출되다"],["滞后","zhìhòu","뒤처지다"],["心肺","xīnfèi","심폐"],["下肢","xiàzhī","하체"]],"tr":["고금은 중국에서 역사가 가장 오래된 현악기 가운데 하나로, 소리가 깊고 아득해 문인들이 마음을 담는 데 자주 썼다.","일부 기업이 ‘주 4일 근무제’를 시범 운영한 결과, 직원의 업무 효율은 그 때문에 떨어지지 않았다.","이 지역에서 최근 인구가 계속 빠져나가는 것은 산업 구조가 단조롭고 공공 서비스가 뒤처졌기 때문이다.","줄넘기는 간단해 보이지만 심폐 기능, 몸의 협응력, 하체 근력을 한꺼번에 단련할 수 있다."],"ow":[[["古琴","gǔqín","고금(칠현금)"],["弹拨乐器","tánbō yuèqì","현을 튕기는 악기"],["悠远","yōuyuǎn","아득하다"],["寄托","jìtuō","의탁하다"]],[["试点","shìdiǎn","시범 실시"],["效率","xiàolǜ","효율"]],[["外流","wàiliú","유출되다"],["单一","dānyī","단일하다"],["滞后","zhìhòu","뒤처지다"],["所致","suǒzhì","~때문에 생기다"]],[["心肺","xīnfèi","심폐"],["协调","xiétiáo","협응"],["下肢","xiàzhī","하체"]]]},{"o":["经过近二十年的规划与建设，使这片曾经荒凉的盐碱滩涂变成了一座产城融合的现代化新城。","许多看似偶然的科学发现，其背后无不凝聚着研究者长期的观察与思考。","随着人口出生率下降，一些幼儿园面临招生困难，不得不转型为托育机构或老年活动中心。","明清时期的晋商以诚信为本，足迹遍布大江南北，其创办的票号被视为中国现代银行的雏形。"],"a":0,"type":"주어 결여","why":"“经过……，使这片滩涂……”에서 经过 구 뒤에 使가 와서 주어가 없다.","fix":"经过近二十年的规划与建设，这片曾经荒凉的盐碱滩涂变成了一座产城融合的现代化新城。","words":[["盐碱","yánjiǎn","염분과 알칼리"],["滩涂","tāntú","갯벌"],["产城融合","chǎn chéng rónghé","산업과 도시의 융합"],["凝聚","níngjù","응집되다"],["托育","tuōyù","영유아 보육"],["晋商","Jìnshāng","산시 상인"],["票号","piàohào","표호(옛 환전 금융점)"],["雏形","chúxíng","초기 형태"]],"tr":["20년 가까이 계획하고 건설한 끝에, 한때 황량했던 이 염분 많은 갯벌은 산업과 도시가 어우러진 현대적인 신도시로 바뀌었다.","우연처럼 보이는 많은 과학적 발견 뒤에는 하나같이 연구자의 오랜 관찰과 고민이 담겨 있다.","출생률이 떨어지면서 일부 유치원은 원아 모집이 어려워져 영유아 보육 기관이나 노인 활동 센터로 바꿀 수밖에 없었다.","명청 시대 산시 상인은 신용을 근본으로 삼아 전국 곳곳에 발자취를 남겼으며, 그들이 세운 표호는 중국 근대 은행의 초기 형태로 여겨진다."],"ow":[[["荒凉","huāngliáng","황량하다"],["盐碱","yánjiǎn","염분과 알칼리"],["滩涂","tāntú","갯벌"],["产城融合","chǎn chéng rónghé","산업과 도시의 융합"]],[["偶然","ǒurán","우연하다"],["无不","wúbù","~하지 않는 것이 없다"],["凝聚","níngjù","응집되다"]],[["出生率","chūshēnglǜ","출생률"],["招生","zhāoshēng","신입생을 모집하다"],["转型","zhuǎnxíng","전환하다"],["托育","tuōyù","영유아 보육"]],[["晋商","Jìnshāng","산시 상인"],["诚信","chéngxìn","신용"],["票号","piàohào","표호(옛 환전 금융점)"],["雏形","chúxíng","초기 형태"]]]},{"o":["竞技健美操是一项在音乐伴奏下完成的运动，兼具健身与表演的双重特点。","古代的驿站不仅负责传递公文，还为往来官员提供食宿和换乘马匹。","投资者在进行理财规划时，切忌不要把全部资金集中投入到单一的高风险产品中。","数字人民币的推广，使支付方式更加多样，也为跨境结算提供了新的选择。"],"a":2,"type":"부정 오류","why":"“切忌”(절대 피하라)에 이미 부정 뜻이 있어 “不要”와 겹치면 ‘하지 않는 것을 피하라’가 된다.","fix":"投资者在进行理财规划时，切忌把全部资金集中投入到单一的高风险产品中。","words":[["切忌","qièjì","절대 삼가다"],["理财","lǐcái","재테크"],["驿站","yìzhàn","역참"],["跨境","kuàjìng","국경을 넘는"],["结算","jiésuàn","결제"],["健美操","jiànměicāo","에어로빅"],["伴奏","bànzòu","반주"],["兼具","jiānjù","겸비하다"]],"tr":["경기 에어로빅은 음악 반주에 맞춰 하는 운동으로, 몸 단련과 공연의 성격을 함께 지닌다.","옛날 역참은 공문을 전하는 일뿐 아니라 오가는 관리에게 숙식과 갈아탈 말도 마련해 주었다.","투자자는 재테크 계획을 세울 때 모든 자금을 위험이 큰 상품 하나에 몰아넣는 일을 절대 피해야 한다.","디지털 위안화가 보급되면서 결제 방식이 더 다양해졌고, 국경을 넘는 결제에도 새로운 선택지가 생겼다."],"ow":[[["竞技","jìngjì","경기, 시합"],["健美操","jiànměicāo","에어로빅"],["伴奏","bànzòu","반주"],["兼具","jiānjù","겸비하다"]],[["驿站","yìzhàn","역참"],["公文","gōngwén","공문서"],["食宿","shísù","숙식"],["马匹","mǎpǐ","말"]],[["理财","lǐcái","재테크"],["切忌","qièjì","절대 삼가다"],["单一","dānyī","단일하다"]],[["推广","tuīguǎng","널리 보급하다"],["跨境","kuàjìng","국경을 넘는"],["结算","jiésuàn","결제"]]]},{"o":["颐和园原名清漪园，始建于清乾隆年间，是我国保存最完整的皇家园林。","越来越多的年轻人愿意为情绪价值买单，盲盒、潮玩等新兴消费因此迅速走红。","人在紧张时心跳加快、手心出汗，是交感神经兴奋的表现。","这项面向小微企业的减税降费政策，有效减轻了企业的生产经营成本，增强了市场主体的活力。"],"a":3,"type":"동사–목적어","why":"“减轻”는 “负担”과 어울리고 “成本”과는 어울리지 않는다. 원가는 “降低”한다.","fix":"这项面向小微企业的减税降费政策，有效降低了企业的生产经营成本，增强了市场主体的活力。","words":[["颐和园","Yíhé Yuán","이화원"],["清漪园","Qīngyī Yuán","청의원"],["乾隆","Qiánlóng","건륭"],["买单","mǎidān","값을 치르다"],["盲盒","mánghé","랜덤 박스"],["走红","zǒuhóng","인기를 끌다"],["交感神经","jiāogǎn shénjīng","교감 신경"],["减税降费","jiǎn shuì jiàng fèi","세금·비용 감면"]],"tr":["이화원의 원래 이름은 청의원으로, 청나라 건륭 연간에 처음 지어졌으며 우리나라에서 가장 잘 보존된 황실 정원이다.","점점 더 많은 젊은이가 기분을 채워 주는 데 기꺼이 돈을 쓰면서 랜덤 박스, 캐릭터 장난감 같은 새로운 소비가 빠르게 인기를 끌었다.","사람이 긴장하면 심장이 빨리 뛰고 손바닥에 땀이 나는 것은 교감 신경이 흥분했다는 표시다.","소기업을 위한 이번 세금·비용 감면 정책은 기업의 생산·경영 원가 부담을 효과적으로 덜어 시장 주체의 활력을 키웠다."],"ow":[[["颐和园","Yíhé Yuán","이화원"],["清漪园","Qīngyī Yuán","청의원"],["乾隆","Qiánlóng","건륭"],["皇家园林","huángjiā yuánlín","황실 정원"]],[["买单","mǎidān","값을 치르다"],["盲盒","mánghé","랜덤 박스"],["潮玩","cháowán","트렌디 장난감"],["走红","zǒuhóng","인기를 끌다"]],[["心跳","xīntiào","심장 박동"],["交感神经","jiāogǎn shénjīng","교감 신경"],["兴奋","xīngfèn","흥분하다"]],[["减税降费","jiǎn shuì jiàng fèi","세금·비용 감면"],["小微企业","xiǎowēi qǐyè","소기업"],["市场主体","shìchǎng zhǔtǐ","시장 주체"]]]},{"o":["南宋时期，随着经济重心的南移，临安一跃成为当时世界上人口最多的城市之一。","为了破解“停车难”，该区利用桥下空间和边角地块新建了一批智能立体停车库，大大缓解了老城区居民夜间停车。","研究表明，蓝鲸的叫声可以在海水中传播上千公里，是动物界最响亮的声音之一。","中国画讲究“留白”，画家常以大面积的空白表现水、天或云雾，给观者留下想象的余地。"],"a":1,"type":"목적어 결여","why":"“缓解了……夜间停车” 뒤에 목적어 중심어 “难的问题”가 빠졌다. ‘주차’ 자체를 완화할 수는 없다.","fix":"为了破解“停车难”，该区利用桥下空间和边角地块新建了一批智能立体停车库，大大缓解了老城区居民夜间停车难的问题。","words":[["重心","zhòngxīn","중심"],["临安","Lín'ān","임안(남송 수도)"],["破解","pòjiě","해결하다"],["地块","dìkuài","부지"],["蓝鲸","lánjīng","대왕고래"],["留白","liúbái","여백을 남기다"],["余地","yúdì","여지"]],"tr":["남송 때 경제 중심이 남쪽으로 옮겨 가면서 임안은 단숨에 당시 세계에서 인구가 가장 많은 도시 가운데 하나가 되었다.","‘주차난’을 풀기 위해 이 구는 다리 밑 공간과 자투리 땅에 스마트 입체 주차장을 새로 지어 구도심 주민의 밤 주차 문제를 크게 덜었다.","연구에 따르면 대왕고래의 울음소리는 바닷속에서 천 킬로미터 넘게 퍼질 수 있으며, 동물계에서 가장 큰 소리 가운데 하나다.","중국화는 ‘여백’을 중시해, 화가는 넓은 빈 공간으로 물이나 하늘, 구름과 안개를 나타내 보는 이에게 상상할 여지를 남긴다."],"ow":[[["南宋","Nán Sòng","남송"],["重心","zhòngxīn","중심"],["临安","Lín'ān","임안(남송 수도)"],["一跃","yíyuè","단숨에 뛰어오르다"]],[["破解","pòjiě","해결하다"],["边角","biānjiǎo","자투리"],["地块","dìkuài","부지"],["立体","lìtǐ","입체"]],[["蓝鲸","lánjīng","대왕고래"],["传播","chuánbō","전파되다"],["响亮","xiǎngliàng","우렁차다"]],[["留白","liúbái","여백을 남기다"],["云雾","yúnwù","구름과 안개"],["余地","yúdì","여지"]]]},{"o":["截至今年六月，这家网约车平台的注册司机已达近一百五十余万人，其中女性司机占比明显上升。","先秦思想家荀子认为，人性本恶，必须通过后天的教化才能向善。","小区周边的便利店、菜市场和社区食堂，构成了居民日常生活中不可或缺的商业网络。","长江江豚是长江中仅存的淡水鲸类，其种群数量是衡量长江生态状况的重要指标。"],"a":0,"type":"어림수 중복","why":"“近”(가까이)과 “余”(남짓)가 함께 쓰여 어림수 표현이 겹치고 뜻도 모순된다.","fix":"截至今年六月，这家网约车平台的注册司机已达一百五十余万人，其中女性司机占比明显上升。","words":[["截至","jiézhì","~까지"],["注册","zhùcè","등록하다"],["先秦","Xiān Qín","선진 시대"],["荀子","Xúnzǐ","순자"],["教化","jiàohuà","교화"],["不可或缺","bù kě huò quē","없어서는 안 되다"],["江豚","jiāngtún","상괭이"],["衡量","héngliáng","가늠하다"]],"tr":["올해 6월까지 이 앱 호출 차량 플랫폼에 등록한 운전기사는 150여만 명에 이르렀고, 그중 여성 기사 비중이 눈에 띄게 늘었다.","선진 시대 사상가 순자는 사람의 본성은 악하므로 뒤에 받는 교화를 거쳐야 선해질 수 있다고 보았다.","단지 주변의 편의점, 재래시장, 동네 식당은 주민 일상에 없어서는 안 될 상업망을 이룬다.","상괭이는 창장에 유일하게 남은 민물 고래류로, 그 개체 수는 창장 생태 상태를 가늠하는 중요한 지표다."],"ow":[[["截至","jiézhì","~까지"],["网约车","wǎngyuēchē","앱 호출 차량"],["注册","zhùcè","등록하다"],["占比","zhànbǐ","차지하는 비중"]],[["先秦","Xiān Qín","선진 시대"],["荀子","Xúnzǐ","순자"],["人性本恶","rénxìng běn è","성악설"],["教化","jiàohuà","교화"]],[["便利店","biànlìdiàn","편의점"],["构成","gòuchéng","구성하다"],["不可或缺","bù kě huò quē","없어서는 안 되다"]],[["江豚","jiāngtún","상괭이"],["仅存","jǐncún","유일하게 남다"],["种群","zhǒngqún","개체군"],["衡量","héngliáng","가늠하다"]]]},{"o":["竹简在纸张普及之前是中国古代最主要的书写材料，东晋以后才逐渐被纸所取代。","城市夜经济的繁荣，不仅取决于商业设施的完善，还与公共交通的运营时间密切相关。","无论是大型连锁商超和社区小店，都在积极探索线上线下融合的新零售模式。","珠穆朗玛峰的高度并非固定不变，由于板块运动，它每年仍在缓慢地上升。"],"a":2,"type":"짝 오류","why":"“无论” 뒤에는 선택을 나타내는 “还是”가 와야 하는데 “和”를 써서 짝이 맞지 않는다.","fix":"无论是大型连锁商超还是社区小店，都在积极探索线上线下融合的新零售模式。","words":[["竹简","zhújiǎn","죽간"],["东晋","Dōng Jìn","동진"],["商超","shāngchāo","대형 마트"],["零售","língshòu","소매"],["珠穆朗玛峰","Zhūmùlǎngmǎ Fēng","에베레스트산"],["板块","bǎnkuài","지각판"]],"tr":["죽간은 종이가 널리 쓰이기 전 중국 고대의 가장 주된 필기 재료였으며, 동진 이후에야 점차 종이로 바뀌었다.","도시 야간 경제의 번영은 상업 시설이 잘 갖춰졌는지에 달렸을 뿐 아니라, 대중교통 운행 시간과도 밀접하게 관련된다.","대형 체인 마트든 동네 작은 가게든, 모두 온라인과 오프라인을 합친 새로운 소매 방식을 적극 찾고 있다.","에베레스트산의 높이는 고정된 것이 아니어서, 지각판 운동 때문에 지금도 해마다 천천히 높아지고 있다."],"ow":[[["竹简","zhújiǎn","죽간"],["普及","pǔjí","널리 보급되다"],["东晋","Dōng Jìn","동진"],["取代","qǔdài","대체하다"]],[["夜经济","yèjīngjì","야간 경제"],["繁荣","fánróng","번영"],["取决于","qǔjué yú","~에 달려 있다"],["运营","yùnyíng","운영하다"]],[["连锁","liánsuǒ","체인"],["商超","shāngchāo","대형 마트"],["零售","língshòu","소매"]],[["珠穆朗玛峰","Zhūmùlǎngmǎ Fēng","에베레스트산"],["并非","bìngfēi","결코 ~이 아니다"],["板块","bǎnkuài","지각판"]]]}]];
